INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(729, 'koKR', 'Roztargniony poszukiwacz', 'Cóż to był za zaszczyt, gdy mistrz Siwowąs przydzielił mnie do pracy pod okiem wielkiego poszukiwacza Remtravela. W akademii w Żelaznej Kuźni wszyscy znali jego wielkie odkrycia.$b$bAle poszukiwacz jest raczej... hmm... nieświadomy... tego, co dzieje się wokół niego.$b$bNatrafiliśmy na ślady wielkiej cywilizacji. Z ziemi wyłoniły się straszliwe golemy i opanowały wykopalisko. Remtravel chyba w ogóle tego nie zauważył. Pobiegłam z powrotem do Auberdine po pomoc.$b$bProszę, udaj się na południe i sprawdź, czy poszukiwaczowi nic się nie stało!', 'Udaj się na południe i sprawdź, co z poszukiwaczem Remtravelem.', '', '', '', '', '', '', 0),
(731, 'koKR', 'Roztargniony poszukiwacz', 'No więc, Hollee... Ach, prawda, ty nie jesteś Hollee. Gdzie jest Hollee?$b$bE tam, nie o to chodzi. Musimy znaleźć ten pędzelek... to znaczy tajemniczą skamieniałość! Musimy znaleźć tę skamieniałość. Liga Odkrywców w Darnassus będzie chciała jakiegoś dowodu, czym się tu zajmowałem.$b$bDaj znać, kiedy będziesz $ggotów:gotowa;, a wyruszymy na poszukiwanie tego pędzelka... to znaczy skamieniałości! Znajdziemy coś na piśmie, co zadowoli Ligę.$b$bNo to jak, już $ggotów:gotowa;?', 'Chroń poszukiwacza Remtravela, gdy będzie szukał tajemniczej skamieniałości, a następnie wróć do archeolożki Hollee w Auberdine.', 'Eskortuj poszukiwacza Remtravela', 'Wróć do archeolożki Hollee w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(943, 'koKR', 'Roztargniony poszukiwacz', 'Oryginalną skamieniałość ma teraz poszukiwacz Whelgar, na swoich wykopaliskach na Bagniskach. Gdy odkryłem Kamień Relu, uwierzyłem, że to klucz do rozwikłania tajemnicy skamieniałości.$b$bKiedy wędrowałem drogą na spotkanie z Whelgarem, napadły mnie raptory i relikt przepadł. Nie wiem, która z tych cętkowanych bestii go połknęła, ale jeśli zdołasz go odzyskać, będę mógł uwolnić moc tych artefaktów.$B$BPrzynieś mi zarówno Kamień Relu, jak i oryginalną skamieniałość, którą ma Whelgar.', 'Przynieś Kamień Relu i skamieniałość Flagonguta archeologowi Flagongutowi w Przystani Menethilów.', '', 'Wróć do archeologa Flagonguta w Przystani Menethilów na Bagniskach.', '', '', '', '', 0),
(944, 'koKR', 'Glewia Mistrza', 'To dziwne, że nagi są tutaj, na Mrocznym Wybrzeżu. Lecz jeszcze dziwniejszy... jest Młot Zmierzchu. Ten kult czci dawnych, prastarych władców ziemi. Władców pokonanych dawno temu.$B$BGlewia Mistrza, na południu, to miejsce, gdzie padł jeden z takich dawnych władców.$B$BUdaj się tam i poszukaj kolejnych kultystów Młota Zmierzchu.$B$BWeź tę fiolkę jasnowidzenia. Gdy przeszukasz Glewię Mistrza, użyj jej, by stworzyć misę wróżebną. Potem przemów do mnie przez tę misę.', 'Zbierz informacje, a następnie użyj fiolki jasnowidzenia, aby stworzyć misę wróżebną. Przez misę porozmawiaj z Onu.', 'Dotrzyj do Glewii Mistrza', 'Wróć do misy wróżebnej.', '', '', '', '', 0),
(945, 'koKR', 'Ucieczka Therylune', 'Pomocy!$B$BWłóczyłam się w okolicy Glewii Mistrza, a ci plugawi kultyści mnie otoczyli. Dobrze, że umiem się chować!$B$BPomożesz mi się stąd wydostać? Muszę też dać znać mojej siostrze Therysil, że nic mi nie jest. Jest w Jesionowej Kniei na południu, w Kaplicy Aessiny.', 'Pomóż Therylune uciec, a następnie powiedz Therysil w Kaplicy Aessiny w Jesionowej Kniei, że jej siostra jest bezpieczna.', 'Wyprowadź Therylune z Glewii Mistrza', 'Wróć do Therysil.', '', '', '', '', 0),
(947, 'koKR', 'Grzyby z jaskini', 'Przygotowuję miksturę, do której potrzebne są rzadkie grzyby – takie, które rosną tylko w pewnej jaskini. Jaskinia leży za Wodospadami Skalnego Źródła, na wschód i nieco na północ, wzdłuż gór.$B$BSam bym się tam udał, lecz Gaj Pradawnych radził mi trzymać się od tego miejsca z daleka. Nasi czcigodni sprzymierzeńcy wyczuwają, że w jaskini kryje się nowe zło Mrocznego Wybrzeża.$B$BProszę, $N, zbierz dla mnie te grzyby. A przy okazji zbadaj jaskinię i sprawdź, czy obawy Pradawnych są słuszne.', 'Przynieś 5 koźlarzy i 1 muchomor sromotnikowy Barithrasowi Księżycowemu Cieniowi w Auberdine.', '', 'Wróć do Barithrasa Księżycowego Cienia w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(948, 'koKR', 'Onu', 'Onu, Pradrzewiec wiedzy z Gaju Pradawnych, wie o twojej wyprawie do Wodospadów Skalnego Źródła i pragnie z tobą pomówić. Gaj leży na południu, u podnóża gór.$B$BPradawni są cierpliwi i mądrzy, $N. Lecz jeśli Onu szuka twojej rady w sprawie tego, co $gujrzałeś:ujrzałaś; przy wodospadach, obawiam się, że sprawa jest pilna.', 'Porozmawiaj z Onu w Gaju Pradawnych.', '', '', '', '', '', '', 0),
(949, 'koKR', 'Obóz Zmierzchu', 'Cel Młota Zmierzchu przy Glewii Mistrza nie jest znany. Lecz musi być mroczny.$B$BPrzeszukaj ich obóz przy Glewii... Szukaj czegoś, co zdradzi nam ich zamiary.$B$BBo musimy poznać ich zamiary, nim ułożymy plan.', 'Znajdź wskazówkę w obozie Młota Zmierzchu przy Glewii Mistrza.', '', '', '', '', '', '', 0),
(950, 'koKR', 'Powrót do Onu', 'Wpatrywanie się w Tom zmierzchu doprowadza do szaleństwa. Już po chwili litery zaczynają pływać i tańczyć, a niegdyś piękne ornamenty wykręcają się w groteskowe kształty.$B$BZdołasz wyrwać tylko jedną stronicę obłąkanych bazgrołów, nim ogarnie cię omdlenie.', 'Zanieś Onu odzyskane obłąkane bazgroły.', '', '', '', '', '', '', 0),
(951, 'koKR', 'Relikwie z Mathystry', 'Pergamin, który $gznalazłeś:znalazłaś; przy Glewii Mistrza, to stronica starożytnego tekstu... spisanego przez elfy! Ciąży na nim silna klątwa i skaża go zepsucie Młota Zmierzchu, lecz wygląda na to, że kult używa starożytnej elfiej magii, by sprowadzić swych dawnych panów z powrotem na nasz świat.$B$BUdaj się do Ruin Mathystry na północnym wschodzie i poszukaj starożytnych relikwii wśród traw i pokruszonych kamieni. Badając je, być może odgadniemy, jak Młot Zmierzchu zamierza wykorzystać magię elfów.', 'Przynieś 6 relikwii z Mathystry Onu w Gaju Pradawnych.', '', 'Wróć do Onu w Dolinie Zmierzchu na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(953, 'koKR', 'Upadek Ameth\'Aran', 'Na wschodzie znajdziesz ruiny Ameth\'Aran. Dziś zamieszkują je niespokojne duchy Wysoko Urodzonych, którzy niegdyś żyli w jego murach, lecz dawniej było to miejsce, gdzie słudzy Aszary swobodnie uprawiali swą potężną magię.$b$bWysłano mnie, abym zbadała ruiny. Natrafiłam na dwie wielkie tablice pokryte opowieściami o Ameth\'Aran i jego upadku. Gdy odczytywałam runy, napadły mnie duchy i musiałam uciec.$b$bProszę, jeśli zdołasz, udaj się do ruin i odczytaj tablice w moim imieniu.', 'Zbadaj tablice opowiadające o Ameth\'Aran i jego upadku, a następnie wróć do strażniczki Tyshy Księżycowego Ostrza na Mrocznym Wybrzeżu.', '', 'Wróć do strażniczki Tyshy Księżycowego Ostrza w Ameth\'Aran na Mrocznym Wybrzeżu.', 'Przeczytaj Pieśń o Ameth\'Aran', 'Przeczytaj Upadek Ameth\'Aran', '', '', 0),
(954, 'koKR', 'Bashal\'Aran', 'Ruiny Bashal\'Aran na wschodzie roją się od demonicznych sług. Duszki i satyry, które zadomowiły się w okolicy, żywią się tutejszą energią magiczną, a ich moc rośnie, im dłużej przebywają w jej zasięgu.$b$bMimo to zauważyłem, że jest jedna kapliczka, do której nie chcą się zbliżać. Po zachodniej stronie ruin, na szczycie niewielkiego urwiska, unosi się dziwna niebieska aura... Musi istnieć wyjaśnienie tej niechęci demonów.$b$bChciałbym, abyś to $gzbadał:zbadała;.', 'Znajdź źródło dziwnej niebieskiej aury w ruinach Bashal\'Aran.', '', '', '', '', '', '', 0),
(955, 'koKR', 'Bashal\'Aran', 'Gdybym miał opowiedzieć historię mego życia, bez wątpienia przekroczyłaby ona granice twej cierpliwości. Powiedzmy, że moje życie było długie i bolesne, a ta widmowa postać jest być może najgorszą męką ze wszystkich.$b$bTrzyma mnie tu magia. Choć moje słowa mogą brzmieć nieszczerze, zapewniam cię, że byłbym niewymownie wdzięczny, gdybyś $gpomógł:pomogła; mi odnaleźć narzędzie mego uwięzienia. Więzi mnie pieczęć, a badając kolczyki duszków i grelli, być może odnajdę jej ślad.', 'Zdobądź 8 kolczyków grella dla Asteriona w Bashal\'Aran.', '', 'Wróć do Asteriona na Skraju Mgły na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(956, 'koKR', 'Bashal\'Aran', 'Jeśli grelle zetknęły się z pieczęcią, która zamyka moje wieczne więzienie, chyba znam przyczynę. Bez wątpienia pieczęć wpadła w ręce satyrów, którzy nimi dowodzą.$b$bCzuję wyraźnie, że tak musi być, $n. Któryś z satyrów z pewnością ją ma. Jeśli zdołasz ją zdobyć, tak bardzo przybliżysz mnie do wyjścia poza kraty mego więzienia, że łzy napłyną mi do oczu.', 'Zdobądź starożytną pieczęć z kamienia księżycowego i zanieś ją Asterionowi w Bashal\'Aran.', '', 'Wróć do Asteriona na Skraju Mgły na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(957, 'koKR', 'Bashal\'Aran', 'Pieczęć, która stworzyła moje więzienie, jest dziełem jednego z najpotężniejszych Wysoko Urodzonych. W Ameth\'Aran, ruinach na południu, bliźniaczych do tych, do dziś płonie pradawny płomień o błękitnej barwie. W tym płomieniu można zniszczyć pieczęć.$b$bUważaj w ruinach, $n...', 'Zniszcz starożytną pieczęć z kamienia księżycowego w pradawnym płomieniu w Ameth\'Aran, a następnie wróć do Asteriona w Bashal\'Aran.', '', 'Wróć do Asteriona na Skraju Mgły na Mrocznym Wybrzeżu.', 'Zniszcz pieczęć w pradawnym płomieniu', '', '', '', 0),
(958, 'koKR', 'Narzędzia Wysoko Urodzonych', '$N. Mam do ciebie prośbę.$b$b$GWidziałeś:Widziałaś; ruiny Ameth\'Aran? Jeśli nie, znajdziesz je po wschodniej stronie głównej drogi, kawałek na południe. Niegdyś były domem wielu potężnych Wysoko Urodzonych, dziś są świadectwem zniszczenia, jakie sprowadziły ich igraszki z magią.$b$bStrażniczki doniosły mi, że duchy Wysoko Urodzonych wciąż trwają i władają swymi pradawnymi magicznymi narzędziami. Trzeba te relikwie przejąć, abyśmy mogli je zniszczyć.', 'Zdobądź 7 relikwii Wysoko Urodzonych dla Thundrisa Wiatrotkacza w Auberdine.', '', 'Wróć do Thundrisa Wiatrotkacza w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(960, 'koKR', 'Onu medytuje', '', '', '', '', '', '', '', '', 0),
(961, 'koKR', 'Onu medytuje', '', '', '', '', '', '', '', '', 0),
(963, 'koKR', 'W imię wiecznej miłości', 'Po bitwach przy Studni Wieczności usłyszałem, że Ameth\'Aran zostało zniszczone, a jego mieszkańcy zginęli – wśród nich moja ukochana, Anaya.$b$bNigdy bym nie pomyślał, że tysiące lat później wspomnienia o Anayi wciąż będą nawiedzać moje sny. Błądząc w otępieniu po lasach Mrocznego Wybrzeża, trafiłem do ruin Ameth\'Aran... gdzie ujrzałem udręczonego ducha mojej ukochanej.$b$bTrzeba ją uwolnić, lecz nie mam na to serca. Jej duch musi zostać zniszczony.', 'Uwolnij ducha Anayi Świtowego Biegu i przynieś jej wisior Cerelleanowi Białemu Pazurowi w Auberdine.', '', 'Wróć do Cerelleana Białego Pazura na Skraju Mgły na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(965, 'koKR', 'Wieża Althalaxxa', 'Witaj, $gmłody przybyszu:młoda przybyszko;. Jestem Elissa Gwiezdna Bryza, a moim zadaniem jest chronić Auberdine przed niebezpieczeństwem.$b$bDlatego wysłałam Balthule\'a Cieniste Uderzenie, by obserwował dziwne wydarzenia wokół Wieży Althalaxxa na północnym wschodzie.$b$bPowinien był wrócić już dawno. Obawiam się, że napotkał w lesie jakieś nieprzewidziane niebezpieczeństwo. Byłabym bardzo wdzięczna, gdybyś go $godnalazł:odnalazła; i $gsprawdził:sprawdziła;, czy wszystko z nim w porządku.', 'Odnajdź Balthule\'a Cieniste Uderzenie w pobliżu Wieży Althalaxxa na Mrocznym Wybrzeżu.', '', '', '', '', '', '', 0),
(966, 'koKR', 'Wieża Althalaxxa', 'Wokół wieży i w jej wnętrzu zadomowiła się grupa czarnoksiężników. Wróciłbym do Auberdine wcześniej, by zdać raport Elissie, ale bałem się, że pod moją nieobecność coś mi umknie.$b$bDelgren podejrzewał, że w wieży może się gromadzić takie towarzystwo, lecz nie wiedział dlaczego.$b$bKilka skrawków pergaminu, które noszą przy sobie czarnoksiężnicy, trafiło w moje ręce, ale potrzebuję więcej, by ułożyć tę układankę. Ostrzegam cię jednak: nie zapuszczaj się do wieży, czarnoksiężnicy w środku są znacznie potężniejsi!', 'Zbierz 4 wytarte pergaminy dla Balthule\'a Cienistego Uderzenia w pobliżu Wieży Althalaxxa.', '', 'Wróć do Balthule\'a Cienistego Uderzenia na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(967, 'koKR', 'Wieża Althalaxxa', 'Mój mistrz, Delgren Oczyszczyciel, to paladyn, który łaskawie zaoferował pomoc w obronie naszych lasów przed siłami demonów i nieumarłych. Wiele mnie nauczył o Świętej Światłości i sztuce walki.$b$bDelgren musi natychmiast dowiedzieć się o poczynaniach kultu.$b$bZnajdziesz go daleko na południe stąd, w Posterunku Maestry w Jesionowej Kniei. Pospiesz się, obawiam się, że zagrożenie ze strony Mrocznej Nici rośnie z każdą godziną.', 'Dostarcz list Balthule\'a Delgrenowi Oczyszczycielowi w Jesionowej Kniei.', '', '', '', '', '', '', 0),
(970, 'koKR', 'Wieża Althalaxxa', 'List Balthule\'a przynosi złe wieści. Ten Kult Mrocznej Nici to cierń w moim boku, który trzeba usunąć. Rozprawiam się z częścią tych szumowin z Mrocznej Nici na północny wschód stąd, w Ordil\'Aran. Jeden z nich ma kamień dusz, który – jak sądzę – kryje sekret potęgi kultu.$b$bPrzynieś mi go, a zdołam odczytać zawarte w nim tajemnice.', 'Zdobądź świecący kamień dusz i zanieś go Delgrenowi Oczyszczycielowi w Posterunku Maestry.', '', 'Wróć do Delgrena Oczyszczyciela w Posterunku Maestry w Jesionowej Kniei.', '', '', '', '', 0),
(973, 'koKR', 'Wieża Althalaxxa', 'Ilkrud Magthrull. Tak, wiem, kim jest. To potężny orczy czarnoksiężnik, który rezyduje w Kaplicy Ognistej Szramy, siedlisku wielkiego zła w południowo-zachodniej części Jesionowej Kniei.$b$bDo tej pory był dla mnie niewiele więcej niż utrapieniem i nie zająłem się nim, ale wygląda na to, że jego czas nadszedł.', 'Przynieś księgę Ilkruda Magthrulla Delgrenowi Oczyszczycielowi w Posterunku Maestry.', '', 'Wróć do Delgrena Oczyszczyciela w Posterunku Maestry w Jesionowej Kniei.', '', '', '', '', 0),
(981, 'koKR', 'Wieża Althalaxxa', 'Za całą twoją pracę należy ci się sowita nagroda. Wróć do Delgrena i powiedz mu, że Athrikus Narassin padł z twojej ręki, a Kult Mrocznej Nici został pokonany i rozproszony.', 'Porozmawiaj z Delgrenem Oczyszczycielem w Posterunku Maestry.', '', '', '', '', '', '', 0),
(982, 'koKR', 'Głęboki ocean, bezkresne morze', 'Na północ od nas, niedaleko brzegów Mrocznego Wybrzeża, leżą dwa wraki – „Srebrny Świt” i „Mglista Zasłona”. Jakiś czas temu oba statki wpadły na te przeklęte murloki, gdy płynęły przez bezkresne morze do Auberdine. Teraz spoczywają na dnie oceanu jako trofea tych bestii.$B$BŻaden z kapitanów nie przeżył tamtej nocy, a ich dzienniki i inne rzeczy wciąż leżą na dnie w kasetkach. Chciałbym, żebyś je dla nas $gwydobył:wydobyła;. Wiele by to znaczyło dla członków załóg, którzy wciąż kręcą się w tych stronach.', 'Wydobądź kasetkę ze „Srebrnego Świtu” i kasetkę z „Mglistej Zasłony” dla Gorbolda Stalowej Dłoni w Auberdine. Obie powinny się znajdować we wrakach statków na północ od osady.', '', 'Wróć do Gorbolda Stalowej Dłoni w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(983, 'koKR', 'Brzęczypudło 827', 'Hej! Pomóż mi z moim najnowszym wynalazkiem – brzęczypudłem. Można przez nie rozmawiać z ludźmi daleko stąd!$B$BMoże już je $gwidziałeś:widziałaś; – to takie skrzynki z dźwigniami. Jedyny kłopot w tym, że ciągle wymagają konserwacji.$B$BKażde szwankuje na inny sposób, ale podjąłem naprawdę sprytną decyzję. Postawiłem każde w pobliżu stworzeń, które mają akurat te części, jakich potrzeba do naprawy danej maszyny. W tej chwili nawala Brzęczypudło 827. Stoi tuż na południe od Auberdine, całkiem blisko. Do naprawy potrzeba 6 odnóży pełzacza. Zapłacę ci...', 'Zbierz 6 odnóży pełzacza i umieść je w Brzęczypudle 827.', '', 'Wróć do Brzęczypudła 827 w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(984, 'koKR', 'Jak wielkie zagrożenie?', 'Kilkoro moich pobratymców uratowano z rąk skażonego furbolga na Teldrassilu, a ja przysiągłem powstrzymać dalsze okrucieństwa, zanim kolejni z nas zostaną ranni... albo spotka ich coś gorszego.$B$BWidziałem już na Mrocznym Wybrzeżu kilka oznak skażenia, ale nie znalazłem jeszcze śladów, że jest powszechne. Rozsądnie byłoby chyba prowadzić dalej dochodzenie wśród furbolgów. Czy odnajdziesz jeden z ich obozów i wrócisz do mnie, jeśli dostrzeżesz jakieś oznaki skażenia?', 'Znajdź obóz skażonych furbolgów na Mrocznym Wybrzeżu i wróć do Terenthisa w Auberdine.', 'Znajdź obóz skażonych furbolgów', 'Wróć do Terenthisa w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(985, 'koKR', 'Jak wielkie zagrożenie?', 'Już $gdowiodłeś:dowiodłaś;, że umiesz wytropić naszego wroga, $N. Czy masz też w sobie to, czego trzeba, by z nim walczyć?$B$BNie wszyscy poszukiwacze przygód przedkładają otwartą walkę nad sztukę skradania się i unikania wroga.$B$BJeśli czujesz się na siłach, to największym zagrożeniem dla naszego ludu jest obecnie obóz furbolgów na południe od Auberdine. Znajdziesz tam część plemienia Czarnego Lasu. Zabij 8 odkrywców i 5 mówców wiatru, a potem wróć do mnie.', 'Zabij 8 odkrywców Czarnego Lasu i 5 mówców wiatru, a następnie wróć do Terenthisa w Auberdine.', '', 'Wróć do Terenthisa w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(986, 'koKR', 'Zaginiony pan', '$N, twoje umiejętności już pomogły mi w moich staraniach. Czy mogę znów prosić cię o pomoc dla Ponurego Pazura i jego pana, Volcora? Mogę też wykonać dla ciebie magiczny płaszcz, dzięki któremu stworzenia Mrocznego Wybrzeża nie będą cię niepokoić, gdy będziesz szukać Volcora.$B$BAby wykonać płaszcz, potrzebuję pięciu pięknych futer z patriarchy lub matriarchy księżycowych tropicieli – inaczej nie starczy materiału. Te koty znajdziesz nad Rzeką Dzikiego Zakola na południu, a nawet dalej na południe, w pobliżu Jesionowej Kniei.', 'Zdobądź 5 pięknych futer księżycowego tropiciela i zanieś je Terenthisowi w Auberdine.', '', 'Wróć do Terenthisa w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(988, 'koKR', '', 'Widzę płaszcz, który masz na sobie, $N. Jeśli zechcesz go poświęcić, odnowię jego magię i użyję go, by uciec. Kłopot w tym, że zostaniesz wtedy w tej jaskini $gsam:sama;.$B$BZdołasz wydostać się stąd o własnych siłach, jeśli wybierzemy tę drogę?$B$BZapewniam cię, że Terenthis nagrodzi cię za pomoc, jeśli to cię martwi.$B$BWybór należy do ciebie, ale naprawdę przydałaby mi się twoja pomoc.', 'Porozmawiaj z Volcorem.', '', 'Wróć do Volcora w Spaczonej Kniei.', '', '', '', '', 0),
(989, 'koKR', '', 'Jeśli zdecydujemy się przebić siłą, plan jest prosty: zejdziemy na drogę i zabijemy każdego furbolga, który stanie nam na drodze... albo cokolwiek innego, co zechce nas zatrzymać.$B$BSzkoda, że nie ma innego sposobu, ale prędzej czy później trzeba będzie rozprawić się z zagrożeniem ze strony furbolgów. Lepiej, żeby stało się to naszymi rękami – wtedy będziemy wiedzieć, że robota jest wykonana.$B$BPoświęć chwilę, by przygotować magię lub broń, jaką masz do dyspozycji, a potem znów ze mną porozmawiaj.', 'Porozmawiaj z Volcorem.', '', '', '', '', '', '', 0),
(993, 'koKR', 'Zaginiony pan', 'Płaszcz jest gotowy, $N. Nadszedł czas, by odnaleźć Volcora. Mogę tylko mieć nadzieję, że zdążymy.$B$BMagia płaszcza, raz przywołana, nie potrwa długo – może pięć minut. Od ciebie zależy, kiedy jej użyjesz: radziłbym zaczekać, aż znajdziesz Ponurego Pazura.$B$BJeśli to, co mi powiedział, jest prawdą, jego pana znajdziesz w jaskini na południe stąd. Ponury Pazur będzie na ciebie czekał przy drodze. Gdy go zobaczysz, pomachaj mu, a wskaże ci drogę do swego pana.', 'Odnajdź Volcora na Mrocznym Wybrzeżu i daj mu zaczarowany płaszcz z księżycowego tropiciela.', '', '', '', '', '', '', 0),
(994, 'koKR', 'Ucieczka siłą', 'Dobrze, $N, a więc siłą. Wynośmy się stąd, gdy tylko będziesz $ggotów:gotowa;. Przebijemy się aż do drogi – Ponury Pazur powinien tam jeszcze być. Tam się rozstaniemy.$B$BTerenthis zechce od razu usłyszeć twoją wersję wydarzeń, więc gdy już się stąd wydostaniemy, udaj się do Auberdine.', 'Chroń Volcora, dopóki nie dotrzecie do drogi, a następnie porozmawiaj z Terenthisem w Auberdine.', 'Pomóż Volcorowi dotrzeć do drogi', 'Wróć do Terenthisa w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(995, 'koKR', 'Ucieczka ukradkiem', 'Dobrze więc... skoro jesteś $gpewien:pewna;, wymkniemy się stąd po cichu. Ruszajmy, gdy będziesz $ggotów:gotowa;.$B$BPamiętaj, gdy już uciekniesz, spotkaj się z Terenthisem w Auberdine. Dotrę tam sam, bo pewnie będę szybszy od ciebie.', 'Ucieknij z jaskini furbolgów i spotkaj się z Terenthisem w Auberdine.', 'Pomóż Volcorowi uciec z jaskini', 'Wróć do Terenthisa w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(1001, 'koKR', 'Brzęczypudło 411', 'Z głębi maszyny dobiega trzeszczący cienki głosik.$B$B„Tu Wizbang! Następne brzęczypudło jest na północ od Auberdine, na plaży.$B$BTo brzęczypudło ma numer 411 i do naprawy potrzebuje 3 oczu młocarza. Młocarze pływają tuż przy brzegu! Młocarze z Mrocznego Wybrzeża... *hik*... Przepraszam...$B$BTak jak ostatnio: gdy dasz brzęczypudłu towar, wypluje twoją nagrodę. *hik*... Co? Nie, nic mi nie jest!”', 'Zdobądź 3 oczy młocarzy z Mrocznego Wybrzeża, żyjących w głębinach w pobliżu Brzęczypudła 411.', '', 'Wróć do Brzęczypudła 411 na Skraju Mgły na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(1002, 'koKR', 'Brzęczypudło 323', 'Brzęczypudło wydaje serię trzasków i słyszysz, jak Wizbang zaczyna mówić.$B$B„Nasztępne brzęczypudło ma numer 323. Szstoi na północ od Auberdine, ale... gdzie jeszt piwo? Co? A, szstoi przy drodze, więc łatwo je znajdziesz koło moshtu.”$B$BWizbang mamrocze coś niezrozumiałego, po czym słychać głośne siorbnięcie.$B$B„Temu trzeba kłów księżycowych tropicieli... 6 szztuk.”', 'Zbierz 6 kłów księżycowego tropiciela i umieść je w Brzęczypudle 323.', '', 'Wróć do Brzęczypudła 323 nad Rzeką Skalnego Źródła na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(1003, 'koKR', 'Brzęczypudło 525', 'Przez bulgotanie i kapanie dobiegające z maszyny przebija się rozchwiany głos Wizbanga.$B$B„Nasztępne jeszt daleko na południe, przy drodze. Nie powinno być trudno je znaleźć... tuż z boku... koło płotu. Chyba schowałem je w krzakach... W krzaczorach. Hehehe... Tak, Brzęczypudło 525 potrzebuje siwych szkalpów z tych siwych osztowych niedźwiedzi. Ale łamaniec językowy. Szsziwe... Hehehe...”$B$BSłyszysz kolejne siorbnięcia, po czym maszyna milknie. Nagle znów ożywa.$B$B„4!”', 'Zbierz 4 siwe skalpy z siwych ostowych niedźwiedzi na południe od Auberdine i umieść je w Brzęczypudle 525.', '', 'Wróć do Brzęczypudła 525 na Brzegu Zmierzchu na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(1133, 'koKR', 'Podróż do Astranaar', '$N, udaj się do Astranaar. Ktoś tak gorliwie oddany Przymierzu jak ty z pewnością zdziała tam wiele dobrego. Porozmawiaj z Shindrell Chyżym Ogniem i zaoferuj jej swoje usługi.$B$BAle nie wspominaj, kto cię przysłał. Shindrell mnie nie zna...', 'Porozmawiaj z Shindrell Chyżym Ogniem w Astranaar.', '', '', '', '', '', '', 0),
(1138, 'koKR', 'Owoce morza', 'Uwielbiam kraby. Kraby to owoce morza! Można je piec, grillować, gotować i opiekać. Smaży się je na patelni, w głębokim tłuszczu i w woku. Jest sałatka z kraba, zupa z kraba, gulasz z kraba, krab z pieprzem, krab z cytryną, krab z korzeniem batożnika i krab-niespodzianka po żelazokuźniańsku. I to... to chyba wszystko.$B$BAkurat teraz łowię ryby, więc nie mogę zdobyć wybornych kawałków kraba. Możesz je wydłubać z pełzaczy rafowych i obrośniętych pełzaczy pływów. Można z nich zrobić mnóstwo rzeczy. Można je piec, grillować, gotować...', 'Zbierz 6 wybornych kawałków kraba dla Gubbera Blumpa w Auberdine.', '', 'Wróć do Gubbera Blumpa w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(1140, 'koKR', 'Wieża Althalaxxa', 'Pismo orków niewiele przewyższa bazgroły dziecka. Wielu z mojego zakonu drwiło, gdy postanowiłem nauczyć się ich mowy, lecz przekonałem się, że warto lepiej rozumieć swoich wrogów.$b$bZ bazgrołów Ilkruda wynika, że Athrikus wciąż ma dwa kamienie dusz, przechowywane na Nocnym Szlaku i w Satyrnaar – terenach zajętych przez satyry w północno-wschodniej części Jesionowej Kniei.$b$bUważaj na siebie, $n. Skąpane we krwi świątynie satyrów potrafią zaniepokoić nawet kogoś tak doświadczonego jak ty.', 'Uwolnij uwięzione dusze Wysoko Urodzonych na Nocnym Szlaku i w Satyrnaar, a następnie wróć do Delgrena Oczyszczyciela w Posterunku Maestry.', '', 'Wróć do Delgrena Oczyszczyciela w Posterunku Maestry w Jesionowej Kniei.', 'Uwolnij duszę Wysoko Urodzonego na Nocnym Szlaku', 'Uwolnij duszę Wysoko Urodzonego w Satyrnaar', '', '', 0),
(1141, 'koKR', 'Rodzina i wędka', 'Uwielbiam łowić ryby. Rodzina Blumpów słynie z wędkowania. Nazywam się Gubber Blump; łowię ryby.$B$BJest taka ryba, którą lubię łowić w tych stronach, nazywa się granik z Mrocznego Wybrzeża. Kiedyś wypływałem łodzią na graniki, ale odkąd wprowadziły się te wredne murloki, żadna łódź już nie wypływa. Założę się, że wyżerają też wszystkie graniki.$B$BSłuchaj, pomożesz mi złowić graniki z Mrocznego Wybrzeża? Dałbym ci za to prawdziwą, autentyczną wędkę rodziny Blumpów! To naprawdę dobra wędka do łowienia ryb.', 'Złów 6 graników z Mrocznego Wybrzeża dla Gubbera Blumpa w Auberdine.', '', 'Wróć do Gubbera Blumpa w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(1143, 'koKR', 'Wieża Althalaxxa', 'Rozumiem. Cóż, jeśli to, co mówisz, jest prawdą, nadszedł czas, by uderzyć. Sądzę, że Athrikus przebywa na szczycie wieży. Uważaj jednak – otacza go wielu potężnych czarnoksiężników, znacznie groźniejszych od tych, z którymi $gwalczyłeś:walczyłaś; wcześniej.', 'Zabij Athrikusa Narassina i przynieś jego głowę Balthule\'owi Cienistemu Uderzeniu w pobliżu Wieży Althalaxxa.', '', 'Wróć do Balthule\'a Cienistego Uderzenia na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(1167, 'koKR', 'Wieża Althalaxxa', 'Zanim zmierzysz się z Athrikusem, rozsądnie byłoby naradzić się z Balthule\'em. Nie wątpię, że czujnie strzegł wieży, i może mieć wieści o tym, co się ostatnio wydarzyło.', 'Porozmawiaj z Balthule\'em Cienistym Uderzeniem w pobliżu Wieży Althalaxxa.', '', '', '', '', '', '', 0),
(1275, 'koKR', 'Badanie skażenia', 'Nierozważne krwawe elfy parają się demoniczną magią. Czyż nie widziały, co spotkało nagi i satyrów Kalimdoru?$b$bObawiam się, że krwawe elfy czeka podobne wynaturzenie. Azeroth nie może sobie pozwolić na narodziny kolejnej plugawej rasy potworów.$b$bPragnę zbadać pnie mózgu satyrów i nag, bym mógł wywnioskować, jaki los czeka elfy. W Czarnych Głębinach, na wybrzeżu Jesionowej Kniei, znajdziesz zarówno satyrów, jak i nagi.$b$bTo długa podróż, $n.', 'Gershala Nocny Szept w Auberdine potrzebuje 8 skażonych pni mózgu.', '', 'Wróć do Gershali Nocnego Szeptu w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(1442, 'koKR', 'W poszukiwaniu klejnotu Kor', 'Witaj, $N. Co mogę uczynić dla kogoś, kto kroczy świętą ścieżką?$B$BAch tak, Stilwell, kowal... sprzed wielu lat. Dobrze go pamiętam, choć od dawna nie słyszałem jego nazwiska.$B$BNigdy nie wydawał mi się zuchwałym człowiekiem, mogę więc tylko przypuszczać, że pragnie klejnotu Kor w szlachetnym celu.$B$BJeśli naprawdę chcesz zdobyć jeden z tych klejnotów, musisz udać się na północny zachód Jesionowej Kniei. Znajdziesz tam Czarne Głębiny, pośród pradawnych ruin. Nagi, które wciąż używają tych klejnotów, przebywają w głębi. Nie idź $gsam:sama;, $N.', 'Przynieś klejnot Kor Thundrisowi Wiatrotkaczowi na Mrocznym Wybrzeżu.', '', 'Wróć do Thundrisa Wiatrotkacza w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(1579, 'koKR', 'Podnośniki majstra', 'Przyjechałem do Auberdine dla spokoju. Chcę wynajdywać swoje wynalazki tam, gdzie jest cicho, bo po nocy picia nie znoszę całego tego hałasu Żelaznej Kuźni!$B$BWięc popłynąłem statkiem do Auberdine i po drodze trochę za dużo wypiłem. Wypadła mi za burtę skrzynka z podnośnikami majstra! Potrzebuję moich podnośników!$B$BNie wiem dokładnie, gdzie mi wypadły, ale jeśli połowisz w oceanie, może ci się poszczęści...', 'Przynieś 8 podnośników majstra Wizbangowi Cranktoggle\'owi w Auberdine.', '', 'Wróć do Wizbanga Cranktoggle\'a w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(1580, 'koKR', 'Elektrośmigła', 'Wiemy, że masz szczęście, ale... jak wielkie, $N?$B$BPewnej nocy włóczyłem się po drogach Mrocznego Wybrzeża. Szukałem dobrej rzeki albo jeziora, żeby wypróbować mój nowy samobieżny, wybuchowy wabik na kaczki, i chyba byłem lekko wstawiony... bo straciłem przytomność i ocknąłem się wiele godzin później w Auberdine. Włosy miałem osmalone, a torba z elektrośmigłami zniknęła! Musiały mi wpaść do wody!$B$BPotrzebuję tych elektrośmigieł! Może zdołasz je wyłowić z jakiegoś jeziora albo strumienia na Mrocznym Wybrzeżu...', 'Przynieś 12 elektrośmigieł Wizbangowi Cranktoggle\'owi w Auberdine.', '', 'Wróć do Wizbanga Cranktoggle\'a w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(2078, 'koKR', 'Zemsta Gyromasta', 'Szczurze lądowy, musisz znaleźć mojego pierwszego oficera.$B$BWeź ten tu klucz, wsadź mu go w łepetynę i przyprowadź go tu, żeby służył Kapitanowi.$B$BTe murloki i ich wódz nie będą zachwycone, jak mój pierwszy oficer się do nich dobierze!', 'Znajdź pierwszego oficera Gelkaka, Młóckotłukatora 4100, i przyprowadź go do Gelkaka.', '', 'Wróć do Gelkaka Gyromasta na Skraju Mgły na Mrocznym Wybrzeżu.', 'Pierwszy oficer Gelkaka', '', '', '', 0),
(2098, 'koKR', 'Zguba Gyromasta', 'Życie pirata nie jest łatwe, szczurze lądowy. To nie tylko łupy i gorzała! Niestety, mój statek poszedł na dno tuż przy brzegu przez te przeklęte threshadony.$B$BPotrzebuję, żeby mój pierwszy oficer znowu był na chodzie!$B$BJak mnie wyrzuciło na brzeg, klucz do mojego pierwszego oficera rozbił się o skały, a bestie z Mrocznego Wybrzeża go rozwlekły. Kątem oka widziałem, jak we wraku grzebią rozwścieczone pełzacze, dzikie borowe biegusy i murloki...', 'Znajdź trzy części klucza Gelkaka i oddaj je Gelkakowi Gyromastowi.', '', 'Wróć do Gelkaka Gyromasta na Skraju Mgły na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(2118, 'koKR', 'Zarażone ziemie', 'Po Mrocznym Wybrzeżu szerzy się choroba, która ogarnia umysły i ciała wszystkich, których dotknie.$B$BNajciężej zaraza dotknęła ostowe niedźwiedzie. Niegdyś szlachetne zwierzęta stały się narzędziem zniszczenia – wściekłe i oszalałe. Być może mam lekarstwo na tę przypadłość.$B$BZanieś tę pułapkę do lasu i połóż ją na ziemi. Każdy wściekły ostowy niedźwiedź, który przejdzie przez jej światło, na krótki czas stanie się łagodny. Gdy niedźwiedź się uspokoi, pójdzie za tobą. Przyprowadź go tutaj, $N.', 'Schwytaj żywego wściekłego ostowego niedźwiedzia i przyprowadź go do Tharnariuna.$B$BJeśli nie uda ci się schwytać wściekłego ostowego niedźwiedzia i stracisz pułapkę, wróć do Tharnariuna Opiekuna Drzew i poproś o kolejną.', '', 'Wróć do Tharnariuna Opiekuna Drzew w Auberdine na Mrocznym Wybrzeżu.', 'Wściekły ostowy niedźwiedź schwytany', '', '', '', 0),
(2138, 'koKR', 'Oczyszczenie zarażonych', 'Tak jak się obawiałem, lekarstwo nie działa.$B$BZ wielkim smutkiem skazuję na śmierć jakiekolwiek stworzenie natury, lecz chore i skażone ostowe niedźwiedzie trzeba zgładzić.$B$BWróć do lasu i zabij 20 wściekłych ostowych niedźwiedzi, $N. Z pewnością nie powstrzyma to zarazy, ale na krótki czas ograniczy szkody, jakie te zwierzęta wyrządzają naszemu lasowi i jego mieszkańcom.', 'Oczyść las z 20 wściekłych ostowych niedźwiedzi i wróć do Tharnariuna Opiekuna Drzew na Mrocznym Wybrzeżu.', '', 'Wróć do Tharnariuna Opiekuna Drzew w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(2139, 'koKR', 'Nadzieja Tharnariuna', 'Przetrwanie naszego ludu i naszych ziem ma swoją smutną cenę, $N.$B$B$GPrzelałeś:Przelałaś; krew sług natury; $gpowaliłeś:powaliłaś; wiele chorych zwierząt. Mieszkańcy Auberdine mają wobec ciebie dług, bo ból lasu zelżał – choćby tylko na chwilę.$B$BMam dla ciebie ostatnie zadanie, lecz ostrzegam: znów przyjdzie ci zabijać. Mam nadzieję, że to ostatni raz, gdy cię wzywam, $N.$B$BW jaskini na północnym wschodzie, niedaleko Bashal\'Aran, mieszka Matka legowiska. Zgładź ją.', 'Znajdź i zabij Matkę legowiska.', '', 'Wróć do Tharnariuna Opiekuna Drzew w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(2178, 'koKR', 'Biegus na obiad', 'Czujesz ten wspaniały zapach? To mój sekretny przepis, $N – świeży gulasz z biegusa. Pyszności!$B$BMoże chcesz poznać przepis?$B$BZanim cię go nauczę, musisz udowodnić, że radzisz sobie z tymi zwierzętami.$B$BNie oczekuję, że pójdziesz, oswoisz jednego i przyjedziesz na nim z powrotem, ale jeśli zabijesz kilka i przyniesiesz trochę ich soczystego mięsa, może dam się przekonać i zdradzę ci tajniki gulaszu z biegusa.', 'Przynieś 5 porcji mięsa biegusa Alanndarian Nocnej Pieśni w Auberdine.', '', 'Wróć do Alanndarian Nocnej Pieśni w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(3524, 'koKR', 'Wyrzucone na brzeg', 'Wiadomo, że majestatyczne morskie stworzenia rzucają się na brzeg Mrocznego Wybrzeża i leżą tam, aż umrą. Ostatnio te zwierzęta trafiają na ląd w coraz większej liczbie. Świątynia Księżyca przysłała mnie tu, bym to zbadała, lecz murloki nad wodą utrudniają mi badania.$B$BTuż na południe od Auberdine leży wyrzucone na brzeg olbrzymie stworzenie, otoczone przez plugawe murloki Szarej Mgły. Czy możesz się tam udać i zdobyć jego kości do naszych badań?', 'Zdobądź kości morskiego stworzenia wyrzuconego na brzeg tuż na południe od Auberdine, a następnie zanieś je Gwennyth Bly\'Leggonde w Auberdine.', '', 'Wróć do Gwennyth Bly\'Leggonde w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(4681, 'koKR', 'Wyrzucone na brzeg', 'To wyrzucone na brzeg stworzenie nie jest tu, na Mrocznym Wybrzeżu, odosobnionym przypadkiem. Jest ich więcej wzdłuż wybrzeża, a nawet w wodzie. Proszę, zbadaj kolejne, o którym wiemy; według doniesień leży w wodzie dokładnie na zachód od Auberdine, w pobliżu zatopionego statku. Przynieś mi wszystko, co zdołasz odzyskać, a co mogłoby pomóc w naszych badaniach.$B$BW swoich wędrówkach możesz też natrafić na inne stworzenia. Jeśli cokolwiek odkryjesz, koniecznie daj nam znać!', 'Odzyskaj szczątki żółwia morskiego ze szkieletu żółwia morskiego w wodach na zachód od Auberdine, a następnie porozmawiaj z Gwennyth Bly\'Leggonde w Auberdine.', '', 'Wróć do Gwennyth Bly\'Leggonde w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(4722, 'koKR', 'Wyrzucony na brzeg żółw morski', 'Znajdujesz truchło żółwia morskiego, który jakiś czas temu wyrzucił się na brzeg Mrocznego Wybrzeża. Ogryzły je murloki, które rozbiły obóz wokół szczątków stworzenia. Mimo to na szczątkach wciąż zostało trochę odpowiednich próbek, które mogłyby się przydać Gwennyth Bly\'Leggonde w Auberdine.', 'Zanieś szczątki żółwia morskiego Gwennyth Bly\'Leggonde w Auberdine.', '', '', '', '', '', '', 0),
(4723, 'koKR', 'Wyrzucone na brzeg morskie stworzenie', 'Szczątki olbrzymiego młocarza – znacznie większego, niż można by się spodziewać na Mrocznym Wybrzeżu – leżą na brzegu Skraju Mgły. Nie wiadomo, jak to stworzenie się tu znalazło; grupa murloków, która teraz ucztuje na jego truchle, wydaje się o wiele za słaba, nawet w dużej liczbie, by powalić taką bestię.$B$BChoć część truchła ogryziono do czysta, zostało go dość, by pobrać próbkę do zbadania dla Gwennyth Bly\'Leggonde w Auberdine.', 'Zanieś kości morskiego stworzenia Gwennyth Bly\'Leggonde w Auberdine.', '', '', '', '', '', '', 0),
(4725, 'koKR', 'Wyrzucony na brzeg żółw morski', 'Kolejne szczątki żółwia morskiego leżą na brzegu. Do skorupy tego żółwia przytroczony jest porzucony kosz transportowy. Być może to stworzenie zostało wypędzone na brzeg przez nieznane istoty, a nie wyrzuciło się samo, jak sugerowały inne szczątki. Murloki Szarej Mgły urządziły sobie teraz w szczątkach tego stworzenia dom i żerują na padlinie.$B$BW koszu znajdujesz pudełko z dziwnymi znakami; może Gwennyth Bly\'Leggonde w Auberdine zdoła coś z nich wyczytać.', 'Zanieś dziwnie oznaczone pudełko Gwennyth Bly\'Leggonde w Auberdine.', '', '', '', '', '', '', 0),
(4727, 'koKR', 'Wyrzucony na brzeg żółw morski', 'Szkielet żółwia morskiego leży w piasku na plażach północnego Mrocznego Wybrzeża. Murloki Szarej Mgły albo nie znalazły tego truchła, albo znalazły, lecz z jakiegoś nieznanego powodu trzymają się od niego z daleka. Tak czy inaczej, z żółwia zostało dość, by zabrać próbkę dla Gwennyth Bly\'Leggonde w Auberdine, do zbadania przez Świątynię Księżyca.', 'Zanieś szczątki żółwia morskiego Gwennyth Bly\'Leggonde w Auberdine.', '', '', '', '', '', '', 0),
(4728, 'koKR', 'Wyrzucone na brzeg morskie stworzenie', 'Na plaży leży częściowo wypatroszone truchło czegoś, co wygląda na olbrzymiego ssaka morskiego. Przy tym ogromnym wyrzuconym na brzeg stworzeniu porzucono taczkę i różne narzędzia, jakby ktoś już wcześniej próbował je zbadać. Choć murloki ogryzły tę bestię, zostało z niej dość, by pobrać odpowiednią próbkę dla Gwennyth Bly\'Leggonde w Auberdine.', 'Zanieś kości morskiego stworzenia Gwennyth Bly\'Leggonde w Auberdine.', '', '', '', '', '', '', 0),
(4730, 'koKR', 'Wyrzucone na brzeg morskie stworzenie', 'Na plaży leży na wpół pożarte truchło czegoś, co mogło być olbrzymim ssakiem morskim. Wokół powalonego stworzenia zamieszkała banda murloków, silniejszych niż te, które żyją bliżej Auberdine. Ze stworzenia zostało dość, by dostarczyć Gwennyth Bly\'Leggonde w Auberdine odpowiednią próbkę jego kości.', 'Zanieś kości morskiego stworzenia Gwennyth Bly\'Leggonde w Auberdine.', '', '', '', '', '', '', 0),
(4731, 'koKR', 'Wyrzucony na brzeg żółw morski', 'Kolejne szczątki żółwia morskiego leżą na brzegu. Do skorupy tego żółwia wciąż jest na wpół przypięty porzucony kosz transportowy. Być może to stworzenie zostało wypędzone na brzeg przez nieznane istoty, a nie wyrzuciło się samo, jak sugerowały inne szczątki. Potężne murloki Szarej Mgły urządziły sobie w truchle tego stworzenia tymczasowy dom.$B$BW koszu znajdujesz pudełko z dziwnymi znakami; może Gwennyth Bly\'Leggonde w Auberdine zdoła coś z nich wyczytać.', 'Zanieś dziwnie oznaczone pudełko Gwennyth Bly\'Leggonde w Auberdine.', '', '', '', '', '', '', 0),
(4732, 'koKR', 'Wyrzucony na brzeg żółw morski', 'Znajdujesz truchło żółwia morskiego, który jakiś czas temu wyrzucił się na brzeg Mrocznego Wybrzeża. Murloki Szarej Mgły, te same, które rozbiły obóz wokół szczątków stworzenia, ogryzły je niemal do czysta. Mimo to na szczątkach wciąż zostało trochę odpowiednich próbek, które mogłyby się przydać Gwennyth Bly\'Leggonde w Auberdine.', 'Zanieś szczątki żółwia morskiego Gwennyth Bly\'Leggonde w Auberdine.', '', '', '', '', '', '', 0),
(4733, 'koKR', 'Wyrzucone na brzeg morskie stworzenie', 'Morze wyrzuciło w skalistej zatoczce Brzegu Zmierzchu szczątki czegoś, co wygląda na olbrzymiego młocarza. Jest kilkakrotnie większy od wszystkich innych młocarzy widzianych w tych stronach. Skądkolwiek przybył, z pewnością nie pochodził z Mrocznego Wybrzeża.$B$BChoć stworzenie zostało miejscami rozszarpane, zostało go dość, by pobrać odpowiednią próbkę dla Gwennyth Bly\'Leggonde w Auberdine.', 'Zanieś kości morskiego stworzenia Gwennyth Bly\'Leggonde w Auberdine.', '', '', '', '', '', '', 0),
(4740, 'koKR', 'POSZUKIWANY: Mętnogłęb!', 'Uwaga!$B$BWyznaczono nagrodę za śmierć murloka zwanego „Mętnogłęb”. Ta plugawa bestia odpowiada za śmierć co najmniej jednej Strażniczki i jest podejrzewana o zatopienie co najmniej dwóch statków towarowych na wodach przy Mrocznym Wybrzeżu!$B$BMętnogłęba widziano ostatnio w obozie murloków z chatami na południe od Auberdine; przypuszcza się, że strzeże tamtejszych chat. Nagrodę można odebrać u strażniczki Glyndy Nal\'Shea w Auberdine.$B$BRada osady Auberdine', 'Odnajdź i zabij murloka zwanego Mętnogłębem. Przypuszcza się, że stworzenie broni chat murloków nad wodą na południe od Auberdine.$B$BZgłoś śmierć Mętnogłęba strażniczce Glyndzie Nal\'Shea w Auberdine.', '', 'Wróć do strażniczki Glyndy Nal\'Shea w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(4761, 'koKR', 'Thundris Wiatrotkacz', 'Wieści z twojego zwiadu w obozie furbolgów powinny dotrzeć do Thundrisa Wiatrotkacza. Łaskawie pełni funkcję starszego Auberdine i mądrze, sprawiedliwie czuwa nad codziennymi sprawami osady. Proszę, podziel się z nim tym, czego dotąd się $gdowiedziałeś:dowiedziałaś; o sytuacji furbolgów.$B$BSądzę, że ma własne przypuszczenia co do przyczyn ich skażenia. Może razem zdołacie wprowadzić w życie plan, który przywróci tu równowagę natury!', 'Porozmawiaj z Thundrisem Wiatrotkaczem w Auberdine.', '', '', '', '', '', '', 0),
(4762, 'koKR', 'Rzeka Skalnego Źródła', 'Rzeka Skalnego Źródła zaczęła się psuć i ulegać skażeniu. Uchodzi do morza przy Skraju Mgły i obawiam się, że wkrótce jej wody dotkną Auberdine. Podejrzewam, że za skażenie odpowiadają furbolgi Czarnego Lasu w górze rzeki, ale podejrzewam też, że nie one są jego prawdziwym korzeniem.$B$BWeź tę probówkę i udaj się do ujścia rzeki na północ stąd. Idź w głąb lądu do pierwszego wodospadu i nabierz próbkę z tamtejszej sadzawki. Nad głową zobaczysz most. Gdy zdobędziesz próbkę, wróć do mnie do Auberdine.', 'Udaj się na północ od Auberdine do pierwszego wodospadu na Rzece Skalnego Źródła i nabierz próbkę z tamtejszej sadzawki.$B$BWróć z próbką z Rzeki Skalnego Źródła do Thundrisa Wiatrotkacza w Auberdine.', '', 'Wróć do Thundrisa Wiatrotkacza w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(4763, 'koKR', 'Skażenie Czarnego Lasu', 'Dowiedzieliśmy się, że jednym ze źródeł skażenia furbolgów są satyrowie. Sprawują nad nimi władzę za pomocą talizmanów, przez które przepuszczają magię. Jeśli furbolgi mają mieć szansę na ocalenie, musimy wywabić satyra skaziciela i odebrać mu ten talizman!$B$BNapełnij tę misę w naszej księżycowej studni i zdobądź próbki pożywienia furbolgów z ich północnego obozu. Wymieszaj je i postaw misę przy ognisku nad rzeką; każdy furbolg, który się pożywi, zostanie oczyszczony na tyle długo, by wywabić satyra skaziciela... którego musisz wtedy zabić!', 'Napełnij pustą misę oczyszczenia w księżycowej studni Auberdine.$B$BZbierz próbki owoców, orzechów i zboża z północnych obozów furbolgów Czarnego Lasu.$B$BWymieszaj zawartość misy i postaw ją przy ognisku najbliższym Rzeki Skalnego Źródła w północnym obozie, aby przywołać satyra skaziciela.$B$BZdobądź talizman splugawienia i zanieś go Thundrisowi Wiatrotkaczowi w Auberdine.', '', 'Wróć do Thundrisa Wiatrotkacza w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(4811, 'koKR', 'Czerwony kryształ', 'Na wschód od nas grasują coraz liczniejsze wrogie lunozwierze. Niegdyś uważano je za łagodne, niemal mistyczne stworzenia. Choć niektórzy wciąż darzą je czcią, bezpieczeństwo Auberdine zmusza mnie do bardziej trzeźwego spojrzenia.$B$BDotarły do mnie wieści, że lunozwierze ciągną do wielkiego czerwonego kryształu w paśmie gór na wschodzie Mrocznego Wybrzeża. Nikt nie ma pojęcia, czym jest ten kryształ ani czy w ogóle istnieje. Odnajdź go tam i zdaj mi relację z tego, co znajdziesz.', 'Udaj się na wschód od Auberdine i poszukaj wielkiego czerwonego kryształu w paśmie gór na wschodzie Mrocznego Wybrzeża. Zdaj relację z tego, co znajdziesz, strażniczce Glyndzie Nal\'Shea w Auberdine.', 'Odnajdź wielki czerwony kryształ w paśmie gór na wschodzie Mrocznego Wybrzeża', 'Wróć do strażniczki Glyndy Nal\'Shea w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(4812, 'koKR', 'Gdy spływa woda', 'Weź tę pustą probówkę i napełnij ją wodą z księżycowej studni tu, w Auberdine. Tak potężna magia powinna nam coś podpowiedzieć co do natury kryształu. W tym celu wylej płyn na kryształ; resztą zajmie się sam.$B$BChoć nie spodziewam się, by coś złego ci się stało, i tak chcę, żebyś $gbył ostrożny:była ostrożna;. Nad nami, na wschodzie, leży Spaczona Knieja; jeśli ten kryształ jest z nią powiązany, jak podejrzewam, może się okazać bardzo niebezpieczny.', 'Napełnij pustą probówkę na wodę w księżycowej studni Auberdine, a następnie zbadaj czerwony kryształ przy górskiej ścianie na wschodzie Mrocznego Wybrzeża.', '', 'Wróć do tajemniczego czerwonego kryształu na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(4813, 'koKR', 'Odłamki we wnętrzu', 'Woda z księżycowej studni ujawniła, że w krysztale tkwi kilka małych odłamków kości, a także połowa żuchwy. Żuchwa wydaje się należeć do istoty człekokształtnej, lecz nie da się tego stwierdzić bez rozbicia kryształu – a tego nie dokonałaby chyba nawet najpotężniejsza magia.$B$BZadanie zostało wykonane; pozostaje tylko zdać relację strażniczce Glyndzie Nal\'Shea w Auberdine.', 'Zdaj relację z tego, co $godkryłeś:odkryłaś;, strażniczce Glyndzie Nal\'Shea w Auberdine.', '', '', '', '', '', '', 0),
(5321, 'koKR', 'Śpiący się przebudził', 'Szedłem do Posterunku Maestry na spotkanie z Liladrisem Księżycową Rzeką, ale postanowiłem się tu zatrzymać i uciąć sobie krótką drzemkę. Odkąd przebudziłem się ze Szmaragdowego Snu, jestem taki senny...$B$B<ziewa>$B$BPokażesz mi drogę? Z tego, co wiem, Posterunek Maestry leży na południe stąd, przy drodze w Jesionowej Kniei. Bywa tam niebezpiecznie, więc mam nadzieję, że masz przyjaciół, którzy do nas dołączą.$B$BI jeszcze jedno: mogę zasnąć, więc jeśli trzeba będzie mnie obudzić, użyj mojego rogu. Znajdziesz go w skrzyni tutaj.', 'Eskortuj Kerloniana Wiecznego Cienia do Liladrisa Księżycowej Rzeki w Posterunku Maestry w Jesionowej Kniei.', 'Eskortuj Kerloniana Wiecznego Cienia do Posterunku Maestry', 'Wróć do Liladrisa Księżycowej Rzeki w Jesionowej Kniei.', '', '', '', '', 0),
(5713, 'koKR', 'Jeden strzał. Jeden trup.', 'Wędrowałam do Auberdine z ważną wiadomością, gdy napadł mnie furbolg Marosh ze swoimi zwiadowcami. Podczas napaści zostałam otruta i ledwo trzymam się na nogach. Potrafię sporządzić odtrutkę, ale minie trochę czasu, nim będzie gotowa.$B$BProszę, broń mnie, dopóki nie zażyję odtrutki. Pomogę ci swoim łukiem, jak tylko zdołam.$B$BJeśli przeżyjemy, dostarczę wiadomość do Auberdine, a ty porozmawiasz z Onaeyą w Posterunku Maestry i opowiesz jej o tym zdarzeniu.', 'Chroń strażniczkę Aynashę, a następnie porozmawiaj z Onaeyą w Posterunku Maestry w Jesionowej Kniei.', 'Chroń Aynashę', 'Wróć do strażniczki Onaei w Jesionowej Kniei.', '', '', '', '', 0),
(6122, 'koKR', 'Główne źródło', 'Wodospady Skalnego Źródła na Mrocznym Wybrzeżu są głównym źródłem wody pitnej w tej krainie, a teraz podejrzewam, że także głównym źródłem trucizny, która szkodzi miejscowej zwierzynie – zwłaszcza jeleniom. Użyj tego próbnika, by nabrać wody u wylotu jaskini; uważaj, bo w jaskini przy wodospadach mieszkają teraz groźne nagi.$B$BGdy go napełnisz, zanieś go Alanndarian Nocnej Pieśni w Auberdine. To ona poprosiła nas o pomoc i razem z nią zajmiesz się tą chorobą.', 'Użyj pustego próbnika z Wodospadów Skalnego Źródła, by nabrać próbkę wody u wylotu jaskini przy wodospadach.$B$BZanieś napełniony próbnik z Wodospadów Skalnego Źródła Alanndarian Nocnej Pieśni w Auberdine na Mrocznym Wybrzeżu.', '', 'Wróć do Alanndarian Nocnej Pieśni w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(6123, 'koKR', 'Składniki lekarstwa', 'Woda posłuży za podstawę leczniczego balsamu, który przygotuję dla jeleni. Dla właściwości leczniczych potrzebuję korzeńca. Zielarze wiedzą, jak go znaleźć, więc jeśli mamy pecha i nie jesteś $gzielarzem:zielarką;, musisz znaleźć kogoś, kto nam pomoże.$B$BWreszcie, dla wzmocnienia działania, potrzebuję księżycowego grzyba. Księżycowe wykwity grzybni łatwo znaleźć; pełno ich w jaskiniach tuż na wschód stąd. W jaskiniach mieszkają lunozwierze, a ostatnio są rozdrażnione, więc uważaj.', 'Przynieś 5 korzeńców i 12 księżycowych grzybów Alanndarian Nocnej Pieśni w Auberdine, by mogła przygotować leczniczy balsam.', '', 'Wróć do Alanndarian Nocnej Pieśni w Auberdine na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(6124, 'koKR', 'Leczenie chorych', 'Z przyniesionych składników wyszło tyle balsamu, że starczy na dziesięć dawek, $N. Dopóki razem z osadą staram się przygotować go więcej, ty pomóż nam zacząć. Po całym Mrocznym Wybrzeżu błąkają się chorowite jelenie; użyj na nich balsamu i ulecz ich niemoc.$B$BDendrite Gwiezdny Płomień w Gaju Luny z pewnością zechce z tobą porozmawiać, gdy skończysz. Przekaż, proszę, podziękowania od Auberdine tamtejszemu Kręgowi Cenariona... a ode mnie przyjmij osobiste podziękowania za twoją pomoc!', 'Użyj leczniczego balsamu dla zwierząt na 10 chorowitych jeleniach na Mrocznym Wybrzeżu, by je uleczyć. Chorowite jelenie widywano od południowego brzegu Rzeki Skalnego Źródła, na północ od Auberdine, aż po południowe krańce Mrocznego Wybrzeża, gdzie zaczyna się Jesionowa Knieja.', '', 'Wróć do Dendrite\'a Gwiezdnego Płomienia w Nocnym Azylu w Gaju Luny.', 'Chorowite jelenie uleczone', '', '', '', 0),
(8721, 'koKR', 'Nestor Gwiezdna Przędza', '', '', '', '', '', '', '', '', 0),
(10752, 'koKR', 'Naprzód, do Jesionowej Kniei', 'Niedawno przez Auberdine przechodziła Raene Wilczy Bieg, w drodze z Darnassus do Jesionowej Kniei; mówiła coś o furbolgach. Nie miałem okazji zapytać o więcej, ale może ty ją odszukasz i udzielisz jej pomocy, $N. Wyjdź z Auberdine południową drogą. Gdy dotrzesz do granicy Jesionowej Kniei, idź dalej drogą. Tam znajdziesz Astranaar i Raene Wilczy Bieg.', 'Porozmawiaj z Raene Wilczy Bieg w Astranaar.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(729, 'koKR', 'Hollee, to ty? Pomóż mi obłupać ten kamień. Podaj mi pędzelek do kamienia, chyba coś widzę.$b$bHej, ty nie jesteś Hollee! Nie $gwidziałeś:widziałaś; przypadkiem mojego pędzelka?$b$bMniejsza z tym! Obiecałem Lidze, że wyślę jej tajemniczą skamieniałość, którą znalazłem. Gdzie się podziała Hollee?$b$bTyle pracy! No i gdzie ta tajemnicza skamieniałość... i mój pędzelek... i Hollee...$b$bA ty kim jesteś... Mniejsza o to, grunt, że jesteś tu, by pomóc.$b$bDaj znać, kiedy będziesz $ggotów:gotowa; zacząć szukać.', 0),
(731, 'koKR', 'Dzięki gwiazdom, poszukiwacz Remtravel jest bezpieczny! Mówiłam ci, że jest roztargniony. Nie mogę uwierzyć, że uparł się tam zostać, kiedy wokół czaiły się te wszystkie okropne stwory.', 0),
(943, 'koKR', 'Znakomicie, $N!$B$BA teraz sprawdźmy, czy za pomocą kamienia zdołam odczytać moc skamieniałości.', 0),
(944, 'koKR', 'Młot Zmierzchu jest przy Glewii Mistrza?$b$bNiedobrze.$b$bDawny władca przebity glewią dawno nie żyje, lecz to nie znaczy, że nie przetrwały okruchy jego mocy.$b$bMłot Zmierzchu musi szukać tej mocy.', 0),
(945, 'koKR', 'Gdzie była moja siostra?? Therylune nie boi się ubrudzić, ale bez przesady! To daleka droga na włóczęgę, a Glewia Mistrza to niezdrowe miejsce...$B$BCóż, dziękuję ci, $N. To bardzo miło z twojej strony, że $gdałeś:dałaś; mi znać, że nic jej nie jest.', 0),
(947, 'koKR', 'Stokrotne dzięki, $N. To wspaniałe okazy!$b$bA gdy $gbyłeś:byłaś; przy Wodospadach Skalnego Źródła, czy $gznalazłeś:znalazłaś; coś, co potwierdza ostrzeżenia Pradawnych?$b$bPradawni są mądrzy, lecz miałem nadzieję, że tym razem się mylą.', 0),
(948, 'koKR', '$N. Jesteś tutaj.$b$bDobrze.$b$bMamy sprawy... do omówienia. Ty i ja.', 0),
(949, 'koKR', 'Ta księga została ręcznie spisana w starożytnym języku i ozdobiona ilustracjami mistrzowskiej ręki.', 0),
(950, 'koKR', 'Ten pergamin z bazgrołami spowija chaotyczna, pierwotna magia. Wyczuwam w nim dzieło Przedwiecznych.$b$bMiejmy nadzieję, że zdradzi nam, jaki cel ma Młot Zmierzchu na Mrocznym Wybrzeżu...', 0),
(951, 'koKR', 'Dziękuję. Te relikwie pochodzą z czasów, gdy Mathystra jaśniała blaskiem. Ten niegdyś wielki bastion elfów podupadł, lecz okruchy jego magii przetrwały. Miejmy nadzieję, że zgłębimy sekrety tego miejsca, nim uczynią to nasi wrogowie...$b$bBądź $gczujny:czujna;, $N.', 0),
(953, 'koKR', 'Mamy niewiele zapisków z czasów Wojny Starożytnych, zwłaszcza z okresu zniszczenia Studni Wieczności. Zważywszy na zamęt i kataklizmy, które wtedy się rozgrywały, nie jest to wielkim zaskoczeniem.$B$BDziękuję, $N. Dzięki twojej pomocy moja praca tutaj dobiegła końca i będę mogła złożyć Kręgowi pełny raport.', 0),
(954, 'koKR', 'Ach... Czemuż to zawdzięczam niezwykle szczególny zaszczyt towarzystwa kogoś takiego jak ty? Doprawdy wiele to mówi o moich obecnych towarzyszach – bez urazy dla moich gospodarzy, szlachetnych grelli i satyrów – że twoją obecność można uznać za poprawę.$b$bLecz proszę, niech mój nieuprzejmy język nie wypędzi cię z tego miejsca. Minęło wiele lat, ba, dziesięcioleci, odkąd miałem kulturalne towarzystwo.', 0),
(955, 'koKR', 'Właśnie tak... Grelle z Bashal\'Aran nie mają tego, czego szukam... lecz niedawno się z tym zetknęły. Niedawno... według twojej miary czasu, nie mojej. Dla mnie „niedawno” sięga za zasłonę przeszłości, niemal w inną Erę...', 0),
(956, 'koKR', 'Trudno mi... trudno mi nawet uwierzyć, że to, co trzymam teraz w dłoni, więziło mnie tak długo. Nie traćmy czasu, $N. Gdy pieczęć zostanie zniszczona, być może znów będę mógł swobodnie przemierzać lasy tego świata.', 0),
(957, 'koKR', 'Jestem wolny, $N! Teraz mogę na własne oczy zobaczyć zmiany, które zaszły w naszym świecie... Znałem jedynie ich strzępy. Pomyśleć, że gdy ostatni raz chodziłem swobodnie, Studnia wciąż istniała, a Wysoko Urodzeni zasiadali na dworze Aszary, naszej ukochanej królowej.$B$BCzuję, że mój strażnik więzienny, mój dawny pan, Athrikus, wciąż żyje... Moje poczucie beznadziei już ustępuje myślom o zemście.', 0),
(958, 'koKR', 'Choć to z pewnością tylko wytwór mojej wyobraźni, niemal czuję na nich skazę plugawej magii Wysoko Urodzonych. Każę je zniszczyć, aby ich długo uśpione zło już nigdy nie zostało uwolnione.', 0),
(961, 'koKR', 'Odkrycie kultystów Młota Zmierzchu jest niepokojące. Muszę rozważyć w medytacji ich zamiary...$B$BGdy zdobędziesz więcej informacji, przemów do mnie przez misę wróżebną. Jeśli potrzebujesz fiolki jasnowidzenia, by stworzyć misę, to... oto kolejna.', 0),
(963, 'koKR', 'Dziękuję, $N. Może byłoby lepiej... gdybym zrobił to sam. Lecz nawet po tych tysiącach lat nie potrafiłem podnieść ręki na moją ukochaną.$b$bProszę, chciałbym zostać sam ze swym żalem...', 0),
(965, 'koKR', 'Przysyła cię Elissa? W takim razie przynosisz dobre wieści. Mam dla niej niepokojące wiadomości, a nie miałem jak ich przekazać.', 0),
(966, 'koKR', 'Stokrotne dzięki, $N. To powinno rzucić nieco światła na to zgromadzenie czarnoksiężników...$b$bHmm... Kult Mrocznej Nici... Nigdy wcześniej nie słyszałem o tej grupie. Nie znając ich historii, niepodobna stwierdzić, jakie mają plany.$b$bNie ma już czasu do stracenia. Trzeba natychmiast ostrzec Delgrena.', 0),
(967, 'koKR', 'Jeśli wolno mi zauważyć, jak na posłańca jesteś całkiem nieźle $gwyposażony:wyposażona;, co? Pewnie Balthule chciał mieć pewność, że jego list trafi w moje ręce. Zobaczmy, co ma do powiedzenia...$B$BTo niepokojące wieści. Gdy tylko pojawiają się nieumarli albo siły demoniczne, pomagam Strażniczkom je niszczyć.$B$BZ początku nie byłem przyzwyczajony do obyczajów nocnych elfów, lecz z czasem nauczyłem się głęboko ich szanować jako sojuszników.', 0),
(970, 'koKR', 'Hmm, ten kamień dusz spowija jakaś mroczna magia. Zobaczmy, co jest w nim uwięzione, dobrze?', 0),
(973, 'koKR', '$GDokonałeś:Dokonałaś; dziś wielkiej rzeczy, $N. Możesz być z siebie $gdumny:dumna;, skoro $gstawiłeś:stawiłaś; czoła tak potężnemu czarnoksiężnikowi.$b$bA teraz zobaczmy, czego możemy się dowiedzieć z pism Ilkruda.', 0),
(981, 'koKR', 'Wiedziałem, że podołasz temu zadaniu, $N.$B$BWyczuwam przed tobą wielkie czyny i wiem, że naprawisz wiele krzywd, które nękają nasze ziemie. Przyjmij moje błogosławieństwo, $N, a także ten dar.', 0),
(982, 'koKR', '$GOddałeś:Oddałaś; nam tu, w Auberdine, wielką przysługę, $gchłopcze:panienko;. Dopilnujemy, by ich rzeczy trafiły tam, gdzie trzeba.$b$bA ty, proszę, przyjmij to. To najmniej, co mogę zrobić dla kogoś, kto miał odwagę naprawić krzywdę.', 0),
(983, 'koKR', 'Gdy wkładasz odnóża pełzacza do maszyny, słyszysz, jak zaczynają zgrzytać tryby. Sądząc po łomotaniu dobiegającym z brzęczypudła, odnóża trafiają na swoje miejsce. Wkrótce maszyna zaczyna buczeć, a z jej wnętrza dobiega cienki głosik.$b$b„Halo? Eee... Halo! $GNaprawiłeś:Naprawiłaś; je! Tu Wizbang, tak przy okazji! Wielkie dzięki... Hej, nie $gchciałbyś:chciałabyś; naprawić jeszcze jednego, co?”', 0),
(984, 'koKR', 'To doprawdy straszne wieści, $N.$B$BSkoro furbolgi są tak blisko Auberdine, musimy się przygotować na nieuniknione.$B$BDziękuję, $N.', 0),
(985, 'koKR', 'Zmyj krew ze swych szat, $N, i nie opłakuj tego, co $gmusiałeś:musiałaś; zrobić. Zamiast tego złóż dziękczynienie. $GZmniejszyłeś:Zmniejszyłaś; zagrożenie dla naszego ludu tu, w Auberdine, choć nad Mrocznym Wybrzeżem wciąż wisi groźba spaczonego mchu.', 0),
(986, 'koKR', 'Świetnie się nadadzą, $N. Od razu zabiorę się do pracy nad płaszczem.$B$BDaj mi kilka chwil, a potem do mnie wróć.$B$BAch, jeszcze jedno: gdy użyjesz zaklęcia płaszcza, twoje kontakty z innymi będą ograniczone. Jeśli zdołasz, poprzestań na rozmowie. Cokolwiek więcej mogłoby rozwiać iluzję.', 0),
(993, 'koKR', 'Wspaniale! Terenthis znalazł kogoś, kto mi pomoże.$b$bA spójrz... płaszcz z księżycowego tropiciela... <kaszle> Och... to boli. Dziękuję, $N.$b$bFurbolgi mnie zraniły, zanim zdołałem im się wymknąć. Daj mi chwilę, a powinienem móc porozmawiać dłużej.', 0),
(994, 'koKR', '$N! Cieszę się, że $gwróciłeś cały i zdrowy:wróciłaś cała i zdrowa;. Twoja pomoc dla Volcora dała mi wiarę, że zdołamy sprostać wyzwaniom, które stoją przed nami tu, na Mrocznym Wybrzeżu, i poza nim.', 0),
(995, 'koKR', '$N! Cieszę się, że $gwróciłeś cały i zdrowy:wróciłaś cała i zdrowa;. Twoja pomoc dla Volcora dała mi wiarę, że zdołamy sprostać wyzwaniom, które stoją przed nami tu, na Mrocznym Wybrzeżu, i poza nim.', 0),
(1001, 'koKR', 'Brzęczypudło budzi się do życia z buczeniem, gdy tylko umieszczasz w nim oczy młocarza. Przez chwilę słychać trzaski, a potem odzywa się znajomy cienki głosik.$B$B„Wino z pełzaczy jeszt najlepsze...” *hik*$B$B„Co? A, już je $gnaprawiłeś:naprawiłaś;? Łał, ale szybko ci poszło. Szo, naprawiszsz jeszcze jedno?”$B$BWydaje ci się, że słyszysz, jak ktoś nalewa płyn do kubka, a potem głośne siorbanie.', 0),
(1002, 'koKR', 'Brzęczypudło nagle rusza do pracy, a z jego wnętrza dobiega wyraźny odgłos zębów mielonych na pył.$b$b„Szo, udało szię! To wszpaniała wiadomoszć... Szo... Może ruszysz w drogę? O! Chyba że chceszsz jeszcze jedną robótkę!”', 0),
(1003, 'koKR', '„Szo, $gwłożyłeś:włożyłaś; szkalpy? To szuper... Co? No, tak, chyba już szię $gpołapałeś:połapałaś;, że mogę z tobą gadać bez tych materiałów w maszynie. Ale mówiłem prawdę, jak mówiłem, że szą zepszute!$b$bBo widziszsz, brzęczypudła to nie tylko narzędzia komunimakacyjne, one też warzą i destylują wyborne trunki. Przeprasham za to oszukańsztwo, ale nocne elfy nie doceniamiają mojego handlu gorzałką w ich miasztach. Włożyłem do tego pudła coś szpecjalnego w podzięce za twoje wysziłki. Szmacznego!”', 0),
(1133, 'koKR', 'Przybywasz, by zaoferować swoje usługi Przymierzu, $N? Z radością przyjmiemy pomoc, bo choć Jesionowa Knieja wciąż jest piękna... nie jest już tak spokojnym miejscem jak niegdyś.', 0),
(1138, 'koKR', 'Łał, właśnie takich wybornych kawałków kraba mi trzeba. Dzięki, $N! Znalazłem to jakiś czas temu przy łowieniu i do niczego mi się nie przyda. Może ty coś z tym zrobisz. Na pewno nie da się z tego zrobić dobrego dania z kraba.$B$BOpowiadałem ci już wszystko o krabach, co?', 0),
(1140, 'koKR', 'Być może zbyt długo pozwalano satyrom trwać w tym lesie. Porozmawiam o tym z Elissą, gdy następnym razem wybiorę się do Auberdine.$B$BTak czy inaczej, po zniszczeniu kamieni dusz moc Athrikusa znacznie osłabnie. Musimy wykorzystać tę okazję, by pozbyć się jego i jego kultu.', 0),
(1141, 'koKR', 'Ale piękne te graniki, $N! Dzięki, że mi $gpomogłeś:pomogłaś;!$B$BJesteś co najmniej tak $gdobrym wędkarzem:dobrą wędkarką; jak moja kuzynka, Graun Blump. Ona też ma brodę i trochę dziwnie pachnie, ale wcale jej to nie przeszkadza w łowieniu. Myślę se, że masz to, czego trza, żeby używać wędki rodziny Blumpów.', 0),
(1143, 'koKR', 'Mam nadzieję, że wraz ze śmiercią Athrikusa demoniczne siły zostaną wyparte z tej okolicy. Nie wątpię, że się przegrupują i powrócą, lecz wtedy będziemy jeszcze lepiej przygotowani, by stawić czoła temu zagrożeniu.', 0),
(1167, 'koKR', 'Ach, dobrze cię znowu widzieć, $N! Dzieją się tu najdziwniejsze rzeczy, cieszę się, że $gprzybyłeś:przybyłaś;!$B$BTo było bardzo dziwne, $N. Wszystko wyglądało normalnie – cóż, na tyle normalnie, na ile to tutaj możliwe – a potem nagle z górnej komnaty wieży buchnął oślepiający błysk. Potem rozległy się krzyki. Wrzaski przeszywały powietrze, a co jakiś czas w ziemię biły błyskawice. Co się dzieje?', 0),
(1275, 'koKR', '$GPrzebyłeś:Przebyłaś; daleką drogę i z pewnością $gstawiłeś:stawiłaś; czoła wielkim niebezpieczeństwom.$B$BTwoje czyny były bezinteresowne. Pomagając mi w badaniach, służysz dobru całego Azeroth. Dziękuję ci, $N, za wszystko, co $gzrobiłeś:zrobiłaś;.$B$BA teraz wybacz, mam wiele pracy...', 0),
(1442, 'koKR', 'To istotnie klejnot, którego pragnie Stilwell, lecz zanim pozwolę ci mu go zanieść, trzeba go oczyścić ze skażenia – wiedźmy nag nasycają klejnoty mocą, to prawda, lecz mocą własną, złą.$B$BPrzekaż Stilwellowi, że moc klejnotu pozostała nienaruszona i powinien się dobrze sprawić w jakimkolwiek rytuale zechce go użyć.$B$BMam nadzieję, że wiesz, co robisz, $N – to, co trzymasz, nie jest zwykłym przedmiotem.', 0),
(1579, 'koKR', 'Nie mogę uwierzyć, że je $gznalazłeś:znalazłaś;! Musisz mieć największego farta w całym Kalimdorze!', 0),
(1580, 'koKR', 'Nie mogę w to uwierzyć! $GZnalazłeś:Znalazłaś; je! Jesteś $gnajlepszym wędkarzem, jakiego:najlepszą wędkarką, jaką; w życiu widziałem!$b$bDziękuję, $N. I proszę, weź to. Choć jesteś tak $gdobry:dobra;, że pewnie tego nie potrzebujesz, pomoże ci to w łowieniu.', 0),
(2078, 'koKR', 'Jarrr... Udowadniasz, żeś ktoś więcej niż tchórzliwy pies morski, szczurze lądowy.$B$BJak tak dalej pójdzie, Kapitan może cię awansować na $gszorowacza:szorowaczkę; rufówki...', 0),
(2098, 'koKR', 'Ahoj, ty parszywy psie morski! Udało ci się! Niedługo mój pierwszy oficer znów będzie na chodzie, a te bestie nie będą wiedzieć, co je trafiło!$B$BHmm, $gwidziałeś:widziałaś; mojego pierwszego oficera?', 0),
(2118, 'koKR', 'Nasza praca dopiero się zaczęła, $N. Czy jesteś $ggotów:gotowa; na kolejne zadanie?', 0),
(2138, 'koKR', '$GOddałeś:Oddałaś; Auberdine wielką przysługę, $N, lecz twoje zadanie jeszcze się nie skończyło.', 0),
(2139, 'koKR', '$GWalczyłeś:Walczyłaś; za Auberdine z odwagą i honorem, $N. Na naszych rozdartych wojną ziemiach śmierć i rozpacz są na porządku dziennym. Wielu nie podejmie wyzwania, jakim jest życie w naszym nowym domu – wolą ukryć się w swoich domostwach albo uciec na lepiej umocnione ziemie Przymierza.$b$bDziękuję ci, $N. Być może wkrótce przyjdzie nam walczyć ramię w ramię przeciw innemu wrogowi.', 0),
(2178, 'koKR', 'Fantastycznie! Spróbuj i powiedz mi, co o tym sądzisz, $N!', 0),
(3524, 'koKR', 'Mam nadzieję, że murloki nie sprawiły ci wielu kłopotów! Dopilnuję, by trafiło to najbliższym hipogryfem do Darnassus. Świątynia Księżyca dała mi trochę funduszy na nagrody za pomoc; przyjmij je, proszę, z naszymi podziękowaniami.$B$BTwój sukces ośmiela mnie, by zaproponować ci dalszą pomoc Świątyni Księżyca, jeśli masz ochotę...', 0),
(4681, 'koKR', 'Bardzo nam dziś $gpomogłeś:pomogłaś; – mamy teraz realną szansę rozwikłać zagadkę, dlaczego te stworzenia wyrzucają się na brzeg Mrocznego Wybrzeża. Myśl, że mogą uciekać z okolic Teldrassilu, jest niepokojąca. Jeśli w swoich wędrówkach natrafisz na kolejne, daj mi znać. Nasze badania dopiero raczkują.$B$BW imieniu Świątyni Księżyca przyjmij to w podzięce za twój trud. Dziękuję, $N!', 0),
(4722, 'koKR', 'Kolejne odkrycie do zbadania – dobra robota, $N! Te szczątki zostaną dokładnie zbadane, gdy trafią do Darnassus. Przyjmij, proszę, to skromne honorarium w zamian za szczątki, które nam $gdostarczyłeś:dostarczyłaś;.', 0),
(4723, 'koKR', 'Kości, które masz, pochodzą od łagodnych ssaków morskich, zamieszkujących wody wokół podnóża Teldrassilu. Nigdy nie słyszano, by gwałtownie wyrzucały się na brzeg, jak zdarzało się to młocarzom. Zastanawiam się, czemu te stworzenia to robią? Cóż, może badanie ich szczątków przyniesie owoce wiedzy, której szukamy.$b$bJeszcze raz dziękuję za pomoc. Przyjmij, proszę, to honorarium od Świątyni Księżyca.', 0),
(4725, 'koKR', 'Słyszałam o takich koszach, jaki nosił na grzbiecie żółw, którego $gznalazłeś:znalazłaś;. Sądzę, że to kosze nag, używane zarówno w bitwie, jak i do przewożenia zaopatrzenia na ląd. Znaki na pudełku, które $gznalazłeś:znalazłaś;, należą do nag; to tłumaczyłoby ich natarczywą obecność na dalekiej północy Mrocznego Wybrzeża.$b$bWyślę to pudełko do Darnassus razem z resztą twoich znalezisk. To dla ciebie – jeszcze raz dziękuję za pomoc.', 0),
(4727, 'koKR', 'Kości, które masz, pochodzą od łagodnych ssaków morskich, zamieszkujących wody wokół podnóża Teldrassilu. Nigdy nie słyszano, by gwałtownie wyrzucały się na brzeg, jak zdarzało się to młocarzom. Zastanawiam się, czemu te stworzenia to robią? Cóż, może badanie ich szczątków przyniesie owoce wiedzy, której szukamy.$B$BJeszcze raz dziękuję za pomoc. Przyjmij, proszę, to honorarium od Świątyni Księżyca.', 0),
(4728, 'koKR', 'Ach, sądzę, że $gtrafiłeś:trafiłaś; na to, które wcześniej badała Liga Odkrywców. Mają tu, na Mrocznym Wybrzeżu, swoich ludzi i wspominali, że badali jedno z wyrzuconych stworzeń, dopóki nie przegoniły ich murloki. Najwyraźniej udało ci się to, co nie udało się ani nam, ani im. Proszę, przyjmij to honorarium w imieniu Świątyni Księżyca.', 0),
(4730, 'koKR', 'Kości, które masz, pochodzą od łagodnych ssaków morskich, zamieszkujących wody wokół podnóża Teldrassilu. Nigdy nie słyszano, by gwałtownie wyrzucały się na brzeg, jak zdarzało się to młocarzom. Zastanawiam się, czemu te stworzenia to robią? Cóż, może badanie ich szczątków przyniesie owoce wiedzy, której szukamy.$B$BJeszcze raz dziękuję za pomoc. Przyjmij, proszę, to honorarium od Świątyni Księżyca.', 0),
(4731, 'koKR', 'Słyszałam o takich koszach, jaki był na grzbiecie tego żółwia. Sądzę, że to kosze nag, używane zarówno w bitwie, jak i do przewożenia zaopatrzenia na ląd. Znaki na pudełku, które $gznalazłeś:znalazłaś;, należą do nag; może stworzenie, które $godkryłeś:odkryłaś;, zginęło w drodze dalej na południe... może do Jesionowej Kniei?$B$BDopilnuję, by to pudełko trafiło do Darnassus razem z resztą twoich znalezisk. To dla ciebie – jeszcze raz dziękuję za pomoc.', 0),
(4732, 'koKR', '$GZnalazłeś:Znalazłaś; jeszcze więcej wyrzuconych na brzeg stworzeń, $N? Nim Nordrassil został zniszczony, żółwie morskie często igrały u jego podnóża. Jednak od narodzin Teldrassilu widuje się je coraz rzadziej. Niektóre, jak odkryliśmy, z nieznanego powodu kończą tu życie.$B$BByć może twoja pomoc pozwoli rozwikłać stojącą przed nami zagadkę. Przyjmij, proszę, to w zamian za szczątki, które nam $gdostarczyłeś:dostarczyłaś;.', 0),
(4733, 'koKR', 'Rozmiary młocarza, o którym mówisz, są oszałamiające. Nawet najstarsze młocarze w tym regionie osiągają zaledwie ułamek takiej wielkości. Choć niegdyś w pobliżu Teldrassilu żyły większe osobniki, ich liczba stale spada. Nie mogę przestać się zastanawiać, czy te stworzenia wyrzucające się tu na brzeg mają z tym coś wspólnego.$B$BGdy będziemy badać przyniesione przez ciebie kości, przyjmij, proszę, to w imieniu Świątyni Księżyca. Dziękuję, $N.', 0),
(4740, 'koKR', 'No proszę, wygląda na to, że $gprzyszedłeś:przyszłaś; nie tylko popytać! Mieszkańcy ucieszą się, że tej nocy będą spać nieco spokojniej i bezpieczniej.$b$bDziś $gwymierzyłeś:wymierzyłaś; sprawiedliwość w imieniu mieszkańców Auberdine, $N. Za to chciałabym wręczyć ci tę stosowną nagrodę... dla $gprawdziwego bohatera:prawdziwej bohaterki; ludu Auberdine.', 0),
(4761, 'koKR', 'Witaj, $N. Twój zwiad w sprawie furbolgów przychodzi w pomyślnej dla nas w Auberdine chwili. Od pewnego czasu zmagamy się nie tylko z mieszkańcami lasu, którzy teraz otwarcie wrogo przyjmują naszą obecność, lecz także z jawnym skażeniem samego lasu. Mam nadzieję, że zdołasz wesprzeć Auberdine w tych niespokojnych czasach.', 0),
(4762, 'koKR', 'Nic dziwnego, że ta woda jest skażona, ale spójrz tylko, jak bardzo zaczyna cuchnąć! Wygląda na to, że trzeba działać raczej prędzej niż później, prawda, $N?$b$bNa wschód od nas leży Spaczona Knieja; to ona jest prawdziwym źródłem tego skażenia, które widziałem już w dawnych czasach. Przewiduję, że ta próbka to potwierdzi. Może zdołamy tu przygotować lekarstwo, lecz by choćby spróbować, będziemy potrzebowali pomocy. Gdy nadejdzie ten czas, $N, mam nadzieję, że udzielisz nam wsparcia.', 0),
(4763, 'koKR', 'Dopiero rozpoczęliśmy tę wojnę o odzyskanie naszego lasu z rąk sił skażenia, lecz dziś wygraliśmy bitwę! $N, mieszkańcy Auberdine mają wobec ciebie dług wdzięczności, którego niełatwo będzie spłacić. Przyjmij, proszę, to wraz z naszymi podziękowaniami. To, czego się dziś dowiedzieliśmy, może pewnego dnia na zawsze uwolnić naszych przyjaciół furbolgów z okowów udręki.', 0),
(4811, 'koKR', 'A więc kryształ istnieje, $N? Fascynujące... Tak czy inaczej, dobrze $gwykonałeś:wykonałaś; zadanie; dobra robota!$B$BCzym właściwie jest ten kryształ? To tylko jedno pytanie w morzu pytań. Kolejne, które przychodzi mi na myśl: czemu lunozwierze ciągną do tego przedmiotu? Czy kryształ jest z natury nieszkodliwy, czy służy jakiemuś bardziej złowrogiemu celowi?$B$BMam jeszcze wiele pytań, ale żeby uzyskać odpowiedzi, będziemy musieli dokładnie zbadać ten kryształ.', 0),
(4812, 'koKR', 'Ponownie $gdotarłeś:dotarłaś; do tajemniczego kryształu. Wyciągasz korek z probówki z wodą z księżycowej studni i ostrożnie wylewasz jej zawartość na wierzchołek kryształu. Gdy woda spływa kaskadą po jego ściankach, widzisz, jak matowa powierzchnia staje się przezroczysta...', 0),
(4813, 'koKR', 'Cóż, wygląda na to, że choć wiemy o tym krysztale więcej, mamy przez to jeszcze więcej pytań bez odpowiedzi!$B$BPrzekażę to, co $godkryłeś:odkryłaś;, radzie Auberdine. Może będą wiedzieć, jak postąpić w sprawie tego kryształu. O ile w ogóle trzeba cokolwiek robić; na razie zagrożenie jest na tyle daleko na wschodzie, że nic nam z jego strony nie grozi.$B$BA ty, proszę, weź to. Potraktuj to jako nagrodę za dobrze wykonaną pracę, $N.', 0),
(5321, 'koKR', 'Och, tak się cieszę, że Kerlonian dotarł! I pewnie zaraz znajdę go gdzieś tu śpiącego, prawda?$b$bDziękuję, że $gpokazałeś:pokazałaś; mu drogę, $N.', 0),
(5713, 'koKR', 'Przynosisz najmilsze wieści, $N. Dobrze słyszeć, że dzięki tobie Aynasha jest cała i zdrowa. Mam nadzieję, że przyjmiesz nagrodę za swoje męstwo. Niech Elune czuwa nad tobą i oświetla ci drogę.', 0),
(6122, 'koKR', 'Na Elunę, ta woda jest obrzydliwa! Nic dziwnego, że jelenie chorują.$B$BCoś zanieczyszcza wodę, a przez to skaża wszystkie wody gruntowe Mrocznego Wybrzeża. Chore jelenie widziano w całej okolicy, nie tylko nad rzeką. Choć ta woda jest najpewniej głównym źródłem szerzącej się choroby, działa tu coś jeszcze.$B$BWierz lub nie, ale ta woda pomoże nam opracować lekarstwo. Gdy będę ją badać, potrzebuję jeszcze kilku rzeczy, by przygotować lekarstwo...', 0),
(6124, 'koKR', 'Dobrze się $gspisałeś:spisałaś;, opiekując się chorowitymi jeleniami Mrocznego Wybrzeża; są nieświadomymi ofiarami większego skażenia i zepsucia, które szerzy się po całej krainie. W Darnassus są tacy, którzy dostrzegają to zagrożenie... i tacy, którzy ignorują narastające oznaki. Mam nadzieję, że nie będziesz z tych, co zamykają oczy na fakty, które patrzą im prosto w twarz, $N.$B$BTak czy inaczej, $gdowiodłeś:dowiodłaś; swej wartości jako $gprzyjaciel:przyjaciółka; natury i Kręgu – przyjmij to jako znak tej przyjaźni.', 0),
(10752, 'koKR', 'Więc Thundris Wiatrotkacz nadal uważa, że trzeba mnie pilnować? Muszę mu przypomnieć, kto kogo uratował; zdaje się zapominać, że to ja wyciągnęłam go z tarapatów.$B$BCóż, skoro już tu jesteś, może znajdę dla ciebie jakieś zajęcie.', 0),
(11740, 'koKR', 'Zbezcześć wielkie ognisko Przymierza na Mrocznym Wybrzeżu!', 0),
(11811, 'koKR', 'Uczcij płomień Mrocznego Wybrzeża!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(731, 'koKR', 'Czy poszukiwacz żyje?', 0),
(943, 'koKR', 'Dzięki Kamieniowi Relu zdołam wydobyć ukryte sekrety mojej skamieniałości, a także skamieniałości Remtravela z Mrocznego Wybrzeża, $N.', 0),
(944, 'koKR', 'Glewia Mistrza, $N.$B$BUdaj się tam, a potem znów ze mną porozmawiaj.', 0),
(947, 'koKR', 'Masz moje grzyby, $N? $GByłeś:Byłaś; w jaskini?', 0),
(950, 'koKR', '$N. Wracasz.', 0),
(951, 'koKR', '$N. Czy twoje przetrząsanie Ruin Mathystry przyniosło owoce?', 0),
(953, 'koKR', 'Gdy już zbadasz tablice i poznasz historię upadku Ameth\'Aran, zaniosę tę wiedzę do Auberdine i powiadomię Krąg Pradawnych.', 0),
(955, 'koKR', 'Gdy będę miał kolczyki, rzucę czar, który wskaże, gdzie jest pieczęć, która mnie więzi. Przez stulecia rozmyślałem o wolności, jaką przyniesie mi jej zniszczenie... Może te stulecia odcisnęły na moim umyśle piętno, z którego nigdy się nie otrząsnę...', 0),
(956, 'koKR', 'Filary tej kapliczki są dla mnie jak kraty więzienia, $N. Żadna siła, jaka mi została, nie zdoła ich skruszyć, a żadna magia, którą władam, zniszczyć...$B$BOd ponad tysiąca lat w nie patrzę i zastanawiam się: gdybym w końcu przetrwał nawet kamień, czy byłbym wolny? A może wtedy więziłyby mnie niewidzialne kraty...', 0),
(957, 'koKR', 'Prawdę mówiąc, $N, boję się... Boję się, że twoje przybycie – to wszystko – jest jedynie wytworem obłąkanego umysłu. Czy wiesz, jaka to męka? Ja... Proszę, musisz się pospieszyć.', 0),
(958, 'koKR', 'Gdyby tylko narzędzia ich zguby przepadły w kataklizmie, który zniszczył nasz świat... Mimo to musimy zrobić, co w naszej mocy, by okropieństwa naszej przeszłości nie powtórzyły się w przyszłości.', 0),
(963, 'koKR', 'Z wielkim smutkiem w sercu podążyłem za Shan\'do Burzogniewnym w sen i zabrałem swój smutek w sny, przesypiając tysiące lat.', 0),
(966, 'koKR', '$GZnalazłeś:Znalazłaś; więcej ich zwojów? Jeśli je zdobędziesz, powinienem zdołać złożyć pełniejszy obraz tego kultu.', 0),
(967, 'koKR', 'Masz do mnie jakąś sprawę, $N?', 0),
(970, 'koKR', '$GZdobyłeś:Zdobyłaś; ten kamień dusz?', 0),
(973, 'koKR', 'Wyglądasz na nieco $gwstrząśniętego:wstrząśniętą;, $n. Dobrze się czujesz?', 0),
(982, 'koKR', 'Kapitanowie tych statków byli dobrymi nocnymi elfami i zasłużyli na lepszy los niż ten, który ich spotkał. Może zatroszczenie się o ich rzeczy osobiste będzie najlepszym sposobem, by ich duchy zaznały spokoju.', 0),
(983, 'koKR', 'Brzęczypudło 827 trwa w złowrogiej ciszy. Pojedyncza migająca lampka wskazuje, że do jego schowka trzeba włożyć 6 odnóży pełzacza.', 0),
(984, 'koKR', 'Jak idą poszukiwania, $N?', 0),
(985, 'koKR', 'Nie cofaj ręki przed tym, co musi zostać zrobione, dziecko. Wiem, jak odrażająca musi być myśl o zabijaniu stworzeń lasu, lecz w tym przypadku to konieczne. Nie znaleziono jeszcze lekarstwa na skażenie, które rozpętało się w lesie, a my musimy robić, co w naszej mocy, by powstrzymać jego postęp, dopóki się go nie znajdzie.', 0),
(986, 'koKR', 'Nie mogę z czystym sumieniem pozwolić ci szukać Volcora, dopóki nie wykonam dla ciebie tego płaszcza.', 0),
(995, 'koKR', 'Tak, $n?', 0),
(1001, 'koKR', 'Właz maszyny jest otwarty, a ona zdaje się wyczekiwać, aż umieścisz w środku 3 oczy młocarza.', 0),
(1002, 'koKR', 'Choć nie $gumieściłeś:umieściłaś; jeszcze w środku 6 kłów księżycowego tropiciela, wydaje ci się, że z wnętrza dobiegają trzaski i bezładna gnomia paplanina. Czyżby ktoś inny zdążył już naprawić maszynę?', 0),
(1003, 'koKR', 'Z Brzęczypudła 525 dobiega śpiew.$b$b„Choć wino z pełzacza jak miód, a piwko z młocarza to cud, i księżycówka z tropiciela wszpaniała – nic nie przebije piwa z ostowego mishia, a wnet go będę miał beczułkę całą!”$b$bWłaz jest otwarty i czeka na 4 siwe skalpy, a piosenka powtarza się w kółko.', 0),
(1138, 'koKR', '...krab z cytryną, krab z korzeniem batożnika i krab-niespodzianka po żelazokuźniańsku. I to chyba wszystko.$B$BO, cześć, $N. Masz te wyborne kawałki kraba, o których ci mówiłem?', 0),
(1140, 'koKR', 'Słyszałem kiedyś szepty, że historia satyrów jest w jakiś sposób powiązana z dziejami nocnych elfów, lecz moi szanowni gospodarze niechętnie o tym mówią.', 0),
(1141, 'koKR', 'Z graników z Mrocznego Wybrzeża można zrobić mnóstwo dobrych potraw. Smaczne są, ale moim zdaniem łowienie ich to większa frajda.$B$B$GZłowiłeś:Złowiłaś; już jakie graniki z Mrocznego Wybrzeża?', 0),
(1143, 'koKR', 'Athrikus Narassin to pradawny i potężny czarnoksiężnik. Może powinniśmy zaczekać na pomoc Delgrena, lecz najwyraźniej bardzo ci ufał, skoro wysłał cię $gsamego:samą;.', 0),
(1275, 'koKR', 'Gdy zbiorę dość próbek do badań, będę mógł rozpocząć właściwą pracę. Mając skażone pnie mózgu zarówno satyrów, jak i nag z Czarnych Głębin, spróbuję znaleźć związek między ich mutacjami.$B$BByć może zdobyta wiedza pozwoli nam powstrzymać krwawe elfy, nim pogrążą się jeszcze głębiej w wynaturzeniu i złu.', 0),
(1442, 'koKR', 'Byłbym mniej ufny wobec kogoś, kto nie kroczy świętą ścieżką, gdyby przyszedł pytać o klejnot Kor. Lecz twoim pobratymcom ufam bardziej niż niektórym z moich. Nie osądzam całego twojego zakonu po czynach jednego upadłego.', 0),
(1579, 'koKR', '$GZnalazłeś:Znalazłaś; moje podnośniki, $N? Bez podnośników nie wyreguluję sztyftów szpyntlowych!', 0),
(1580, 'koKR', '$GZnalazłeś:Znalazłaś; jakieś elektrośmigła? Będą mi potrzebne, jeśli mam dalej badać wabiki na kaczki...', 0),
(2078, 'koKR', 'Gdzie mój pierwszy oficer, $N? Jak się nie pospieszysz, zaraz pójdziesz w kajdany i do rekinów!', 0),
(2098, 'koKR', '$GZnalazłeś:Znalazłaś; mój połamany klucz, szczurze lądowy?', 0),
(2118, 'koKR', '$GPrzyprowadziłeś:Przyprowadziłaś; mi chore zwierzę, $N?$B$BJeśli pułapka nie zadziała, nie martw się – Nadzieja Tharnariuna nigdy nie gaśnie. Jeśli potrzebujesz kolejnej pułapki, porzuć zadanie i wróć do mnie.', 0),
(2138, 'koKR', 'Czy twoje zadanie zostało wykonane?', 0),
(2139, 'koKR', 'Teraz, gdy zarażona Matka legowiska nie żyje, na nasze ziemie wkracza mniej wściekłych ostowych niedźwiedzi. Nie trać czasu, $N.', 0),
(2178, 'koKR', 'Garnek jest pusty, a ja jestem głodna! Czemu tak długo to trwa?', 0),
(3524, 'koKR', 'Te stworzenia dopiero od niedawna trafiają na brzeg Mrocznego Wybrzeża w tak niepokojącej liczbie. Nie mogę oprzeć się wrażeniu, że to jakiś zły omen. Próbka kości tego stworzenia z południa pomogłaby nam w Darnassus ocenić sytuację!', 0),
(4681, 'koKR', 'Gdy zbadasz szczątki stworzenia w wodzie na zachód stąd, będę mogła złożyć porządny raport Świątyni Księżyca w Darnassus. Może wtedy zbliżymy się do odkrycia, dlaczego te nieszczęsne stworzenia kończą życie na brzegu Mrocznego Wybrzeża.', 0),
(4722, 'koKR', 'Witaj, $N – czy masz do zgłoszenia jakieś odkrycia stworzeń wyrzuconych na brzeg?', 0),
(4723, 'koKR', 'Witaj ponownie, $N! Masz do zgłoszenia kolejne odkrycie?', 0),
(4725, 'koKR', 'Miło cię znowu widzieć, $N. Czynimy wielkie postępy w wyjaśnianiu zagadki, dlaczego majestatyczne morskie stworzenia wyrzucają się na brzeg Mrocznego Wybrzeża, lecz zdaje się, że każda odpowiedź rodzi dwa kolejne pytania.$b$bCzy przychodzisz, by dalej wspierać nasze badania?', 0),
(4727, 'koKR', 'Witaj ponownie, $N! Masz do zgłoszenia kolejne odkrycie?', 0),
(4728, 'koKR', 'Witaj ponownie, $N! Co cię sprowadza z powrotem do Auberdine? Może masz do zgłoszenia kolejne odkrycie?', 0),
(4730, 'koKR', 'Witaj ponownie, $N! Masz do zgłoszenia kolejne odkrycie?', 0),
(4731, 'koKR', 'Witaj ponownie, $N. Praca, którą $gwykonałeś:wykonałaś; dla Świątyni Księżyca, jest znakomita. Czy znów pobłogosławisz nas swoim trudem?', 0),
(4732, 'koKR', 'Witaj ponownie, $N – czy masz kolejne odkrycia do zgłoszenia Świątyni Księżyca?', 0),
(4733, 'koKR', 'Dzięki niech będą Elunie – cieszę się, że znów cię widzę, $gdrogi:droga; $N. Świątynia Księżyca wciąż prowadzi tu, na Mrocznym Wybrzeżu, badania nad dziwnym zjawiskiem wyrzucania się stworzeń na brzeg. Czy masz nam coś jeszcze do zaoferowania?', 0),
(4740, 'koKR', 'Witaj, $N – w czym Strażniczki mogą ci dziś pomóc? Może przychodzisz zapytać o nagrodę za Mętnogłęba?', 0),
(4762, 'koKR', 'Zanieczyszczenie Rzeki Skalnego Źródła to dopiero początek niepokojącego zjawiska na Mrocznym Wybrzeżu. Dostarczona przez ciebie próbka pomoże nam opracować plan... jak zaczynam podejrzewać, plan ataku.', 0),
(4763, 'koKR', 'Talizman splugawienia to złowrogie narzędzie, które służy jedynie wypaczaniu równowagi natury. Gdy odbierzesz go satyrowi, który dręczy furbolgi, i przyniesiesz mi, abym mógł go zniszczyć, odniesiemy dziś wielkie zwycięstwo!', 0),
(4811, 'koKR', 'Co masz do zgłoszenia w sprawie tego czerwonego kryształu? Czy on w ogóle istnieje?', 0),
(4812, 'koKR', 'Kryształ wygląda bardzo obco na tle leśnego krajobrazu Mrocznego Wybrzeża. Wydaje ci się, że z jego głębi dobiega bardzo ciche buczenie.', 0),
(5321, 'koKR', 'Czy Kerlonian już dotarł?', 0),
(5713, 'koKR', 'Czy $gwidziałeś:widziałaś; na drodze strażniczkę Aynashę? Wyruszyła z ważną misją, ale jeszcze nie wróciła.', 0),
(6122, 'koKR', 'To ciebie przysłał Krąg Cenariona z Gaju Luny? Wspaniale! Mamy tu niezły kryzys z tymi biednymi jeleniami i cieszymy się z każdej pomocy.$B$BMasz próbkę wody, o której mówił Dendrite Gwiezdny Płomień? Uprzedził mnie, że ją nabierzesz, żebyśmy razem mogli pracować nad lekarstwem...', 0),
(6123, 'koKR', 'Masz składniki, których potrzebuję do balsamu? Jeleniom samo z siebie się nie polepszy, więc lepiej się pospieszmy!', 0),
(6124, 'koKR', 'Czy $gwykonałeś:wykonałaś; to, o co prosiła cię Alanndarian Nocna Pieśń z Auberdine? Dopóki tego nie zrobisz, twoja praca nie jest skończona.', 0),
(11304, 'koKR', 'Tak, $n?', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(2930, 0, 'koKR', 'Skażenie wkrada się do gaju natury. Las trzeba chronić za wszelką cenę.', 0),
(3663, 0, 'koKR', 'Dzień dobry, $gchłopcze:dziewczyno;! Może pomożesz mi z paroma sprawami, którymi trzeba się zająć.', 0),
(3666, 0, 'koKR', 'Hmm... Mogę podłączyć ten drucik tutaj i to zasili zębatkę fizzletańską, ale wtedy hydrokołnierz będzie potrzebował zapasowego źródła zasilania... Może uda mi się... O, cześć! Hej, chcesz mi pomóc wypróbować nowy wynalazek?', 0),
(4456, 0, 'koKR', 'Nie, Długie Uszy to nie moje prawdziwe nazwisko. I nie powiem ci, jak się naprawdę nazywam, więc nawet nie pytaj.', 0);
