INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(361, 'koKR', 'Mistrzu Delgrenie,$B$Bstało się tak, jak się obawiałeś. Twoje przypuszczenia co do Wieży Althalaxxa okazały się słuszne. Przy wieży zebrał się kult, w którego szeregach jest wielu czarnoksiężników, a nawet plugawy satyr. Nazywają siebie Kultem Mrocznej Nici. Nie potrafię sobie wyobrazić, jaki nikczemny cel ich łączy, ale budzi to mój niepokój.$B$BWybacz zwięzłość tego listu, lecz w otaczającym mnie lesie czai się niebezpieczeństwo i niewiele słów mogę poświęcić na opisanie sytuacji. Sam', 0),
(437, 'koKR', 'dostarczyłbym ci tę wiadomość, lecz boję się odejść, by nie przeoczyć czegoś wielkiej wagi.$B$BJeśli zechcesz dowiedzieć się więcej o tym, co zaobserwowałem przy Wieży Althalaxxa, doręczyciel tego listu udzielił mi niemałej pomocy i sądzę, że można $gmu:jej; zaufać.$B$BW pośpiechu,$BBalthule Cieniste Uderzenie', 0),
(443, 'koKR', 'Nie przestaje mnie zdumiewać, jak łatwo nienawiść pozwala naginać innych do swojej woli. Z orkami i trollami poszło najłatwiej – ich nienawiść do Przymierza sprawiła, że chętnie wysłuchali przesłania Mrocznej Nici. Czy choć przeczuwają, jakiej większej potędze służą?$B$BTen nieznośny paladyn, Delgren Oczyszczyciel, wtyka nos w nasze sprawy w Jesionowej Kniei, a jego pachołek Balthule szpieguje moją wieżę w przekonaniu, że nic o nim nie wiem. Delgren uważa nas za pomniejsze', 0),
(444, 'koKR', 'zagrożenie, ot, kolejny kult śmierci. Nie ma pojęcia, że jesteśmy zaledwie jedną z... nici Rady Cieni.$B$BGdy byłem dzieckiem, opowiedziano mi o owadzie, którego ukąszenie z łatwością zabijało, choć wyglądał jak zwykła mucha, drobina ledwie warta uwagi. Najbardziej ranią te rzeczy, które lekceważysz i zostawiasz, by się jątrzyły.', 0),
(1854, 'koKR', 'Wysokie elfy pod wodzą Dath\'Remara opuściły Kalimdor i rzuciły wyzwanie sztormom Wiru. Ich floty przez wiele długich lat błąkały się wśród szczątków świata, a w swej wędrówce odkryły liczne tajemnice i zaginione królestwa. Dath\'Remar, który przybrał imię Słońcobieżca (czyli „ten, który kroczy dniem”),\n szukał miejsc o znacznej mocy linii sił, na których mógłby zbudować swemu ludowi nową ojczyznę.', 0),
(1855, 'koKR', 'Jego flota przybiła w końcu do brzegów królestwa, które ludzie nazwali później Lordaeronem. Wysokie elfy ruszyły w głąb lądu i założyły osadę wśród spokojnych Polan Tirisfal. Po kilku latach wielu z nich zaczęło popadać w szaleństwo. Przypuszczano, że pod tą częścią świata śpi coś złego, lecz tych pogłosek nigdy nie potwierdzono. Wysokie elfy zwinęły obóz i ruszyły na północ, ku innej krainie bogatej w energię linii sił.', 0),
(1856, 'koKR', 'Gdy wysokie elfy przemierzały surowe, górzyste ziemie Lordaeronu, ich wędrówka stawała się coraz bardziej niebezpieczna. Odcięte od życiodajnej energii Studni Wieczności, wiele z nich zapadało na zdrowiu w mroźnym klimacie lub umierało z głodu. Najbardziej niepokojące było jednak to, że nie były już nieśmiertelne ani odporne na żywioły. ', 0),
(1857, 'koKR', 'Zmalały też nieco, a ich skóra utraciła charakterystyczny fioletowy odcień. Mimo trudów spotkały wiele cudownych stworzeń, jakich nigdy nie widziano w Kalimdorze. Natrafiły też na plemiona prymitywnych ludzi, którzy polowali w pradawnych puszczach. Najgroźniejszym wrogiem, jakiego napotkały, okazały się jednak żarłoczne i przebiegłe leśne trolle z Zul\'Aman.', 0),
(1858, 'koKR', 'Te trolle o skórze barwy mchu potrafiły odtwarzać utracone kończyny i leczyć ciężkie rany, lecz okazały się barbarzyńską, złą rasą. Imperium Amanów rozciągało się na większej części północnego Lordaeronu, a trolle zawzięcie walczyły, by nie dopuścić nieproszonych obcych do swoich granic. Elfy znienawidziły okrutne trolle i zabijały je, gdy tylko je napotkały.', 0),
(1859, 'koKR', 'Po wielu długich latach wysokie elfy znalazły wreszcie krainę, która przypominała Kalimdor. Głęboko w północnych lasach kontynentu założyły królestwo Quel\'Thalas i poprzysięgły stworzyć potężne imperium, przy którym imperium ich kuzynów Kaldorei wydałoby się karłowate. Niestety wkrótce odkryły, że Quel\'Thalas założono na miejscu pradawnego miasta trolli, które trolle wciąż uważały za święte. Niemal natychmiast trolle zaczęły masowo atakować elfie osady. ', 0),
(1860, 'koKR', 'Uparte elfy, niechętne oddać swą nową ziemię, posłużyły się magią, którą poznały dzięki Studni Wieczności, i powstrzymywały dzikie trolle. Pod przywództwem Dath\'Remara zdołały pokonać bandy wojenne Amanów, dziesięciokrotnie liczniejsze od nich. Niektóre elfy, pomne dawnych ostrzeżeń Kaldorei, obawiały się, że używanie magii może zwrócić uwagę wygnanego Płonącego Legionu. ', 0),
(1861, 'koKR', 'Postanowiły więc ukryć swoje ziemie za ochronną barierą, która wciąż pozwalałaby im rzucać zaklęcia. Wzniosły w różnych miejscach wokół Quel\'Thalas szereg monolitycznych kamieni runicznych, które wyznaczały granice magicznej bariery. Kamienie runiczne nie tylko ukrywały magię elfów przed zagrożeniami z innych wymiarów, ale też odstraszały zabobonne bandy wojenne trolli.', 0),
(1862, 'koKR', 'Z biegiem czasu Quel\'Thalas stało się lśniącym pomnikiem wysiłków i magicznej biegłości wysokich elfów. Jego przepiękne pałace wznoszono w tym samym stylu co pradawne sale Kalimdoru, lecz wplatano je w naturalne ukształtowanie terenu. Quel\'Thalas stało się lśniącym klejnotem, o którego stworzeniu elfy tak długo marzyły. ', 0),
(1863, 'koKR', 'Władzę nad Quel\'Thalas objęła Rada Srebrnej Luny, choć dynastia Słońcobieżców zachowała pewien wpływ polityczny. Rada, złożona z siedmiu najpotężniejszych panów wysokich elfów, dbała o bezpieczeństwo elfich ziem i ludu. Otoczone ochronną barierą wysokie elfy nie przejmowały się dawnymi ostrzeżeniami Kaldorei i nadal jawnie używały magii niemal w każdej dziedzinie życia. ', 0),
(1864, 'koKR', 'Przez blisko cztery tysiące lat wysokie elfy żyły w pokoju, w zaciszu swego odosobnionego królestwa. Mściwe trolle nie dały się jednak tak łatwo pokonać. Knuły i spiskowały w głębi lasów, czekając, aż ich bandy wojenne się rozrosną. W końcu potężna armia trolli wyroiła się z mrocznych lasów i ponownie obległa lśniące iglice Quel\'Thalas. ', 0);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(3334, 'koKR', '$N, przybyłem, by zbadać, jak bardzo spaczony mech rozprzestrzenił się na Mrocznym Wybrzeżu. Skażenie Teldrassilu i okolicznych ziem bardzo niepokoi druidów Kręgu Cenariona i wszystkie nocne elfy.$B$BMoim celem jest dowiedzieć się, dlaczego do tego doszło, i położyć temu kres.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(50023, 'koKR', 'Skażenie wkrada się do gaju natury. Las trzeba chronić za wszelką cenę.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(6669, 1, 0, 'koKR', 'JARRR! Majtku, coś ty $gnarobił:narobiła;?! Oszalał! Zamknąć go pod pokładem! Podnieść maszt! ARRRR! Ratuj się, kto może!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(825, 'koKR', 'Nigdy nas nie pokonacie!', 'Nigdy nas nie pokonacie!', 0),
(826, 'koKR', 'Moja śmierć niewiele znaczy... Młot i tak spadnie!', 'Moja śmierć niewiele znaczy... Młot i tak spadnie!', 0),
(827, 'koKR', 'Oddaję życie za moich panów. Radujcie się!', 'Oddaję życie za moich panów. Radujcie się!', 0),
(828, 'koKR', 'Przeklinam cię!', 'Przeklinam cię!', 0),
(829, 'koKR', 'Chwała i krew dla Przedwiecznych!', 'Chwała i krew dla Przedwiecznych!', 0),
(830, 'koKR', 'Panowie moi! Idę do was!', 'Panowie moi! Idę do was!', 0),
(831, 'koKR', 'Wasze zwycięstwo tylko przybliża waszą zgubę!', 'Wasze zwycięstwo tylko przybliża waszą zgubę!', 0),
(832, 'koKR', 'Mamusiu!', 'Mamusiu!', 0),
(833, 'koKR', 'Intruzi! Zabić ich!', 'Intruzi! Zabić ich!', 0),
(834, 'koKR', 'Za naszych Panów!', 'Za naszych Panów!', 0),
(835, 'koKR', 'Panowie, tę ofiarę składam wam!', 'Panowie, tę ofiarę składam wam!', 0),
(836, 'koKR', 'Rzeź! Obym przelał krew w Jego imię!', 'Rzeź! Obym przelał krew w Jego imię!', 0),
(837, 'koKR', 'Przyjmij swój koniec!', 'Przyjmij swój koniec!', 0),
(838, 'koKR', 'Do walki! Czuję twój strach, $N!', 'Do walki! Czuję twój strach, $N!', 0),
(839, 'koKR', 'Nadchodzi śmierć! Radujcie się!', 'Nadchodzi śmierć! Radujcie się!', 0),
(840, 'koKR', 'Intruzi! Dobrze, zaczynałem się nudzić...', 'Intruzi! Dobrze, zaczynałem się nudzić...', 0),
(908, 'koKR', '', 'Duchy lasu są niespokojne...', 0),
(909, 'koKR', '', 'Plemię Czarnego Lasu zakłóca spokój naszych świętych ziem.', 0),
(910, 'koKR', '', 'Trzeba coś zrobić z plemieniem Czarnego Lasu.', 0),
(911, 'koKR', '', 'Skaza plami nasz święty las.', 0),
(912, 'koKR', '', 'Nie wolno pozwolić, by plemię Czarnego Lasu zakłócało bieg natury.', 0),
(913, 'koKR', '', 'Wyczuwam niebezpieczeństwo w głębi gaju...', 0),
(925, 'koKR', 'Dobrze, $n, chodźmy poszukać miejsca, gdzie zostawiłem tę tajemniczą skamieniałość. Za mną!', '', 0),
(926, 'koKR', 'Gdzie ja położyłem tę tajemniczą skamieniałość? Aha, może tam na górze...', '', 0),
(927, 'koKR', 'Hmm, tu na górze nic nie ma.', '', 0),
(928, 'koKR', 'Tajemniczej skamieniałości tu nie ma... Ale jest mój egzemplarz „Zielonych wzgórz Cierniodławów”. Cóż to za dobra książka!', '', 0),
(929, 'koKR', 'Założę się, że zostawiłem ją w namiocie!', '', 0),
(930, 'koKR', 'Ach, chwileczkę, to namiot Hollee... i jest pusty.', '', 0),
(931, 'koKR', 'Ciekawe... Wcześniej tego nie zauważyłem...', '', 0),
(932, 'koKR', '%s ogląda starożytny, porośnięty mchem kamień.', '', 0),
(933, 'koKR', 'Ach, zaraz! Przecież miałem szukać tej tajemniczej skamieniałości!', '', 0),
(935, 'koKR', 'Nie, tu z tyłu jej nie zostawiłem!', '', 0),
(936, 'koKR', 'Ach, już pamiętam! Dałem tajemniczą skamieniałość Hollee! Zapytaj ją.', '', 0),
(937, 'koKR', '%s wraca do pracy, nie zważając na nic wokół siebie.', '', 0),
(938, 'koKR', 'O rety! A cóż to? Pomocy!', '', 0),
(939, 'koKR', 'Patrz, cośmy odkopali – $n! Pomóż mi to zabić!', '', 0),
(940, 'koKR', 'Pomocy! $n nie chce się ode mnie odczepić!', '', 0),
(941, 'koKR', 'Coś mi mówi, że $n też chce tajemniczej skamieniałości. Pomocy!', '', 0),
(942, 'koKR', '$n! Pomocy!', '', 0),
(943, 'koKR', 'Pomożesz mi? $n nie daje mi spokoju!', '', 0),
(1188, 'koKR', '', 'Resztę drogi pokonam sama, $n. DZIĘKUJĘ!', 0),
(1189, 'koKR', '', 'Dobrze, ruszajmy!', 0),
(1210, 'koKR', 'Wodospady Skalnego Źródła leżą wzdłuż gór na północnym wschodzie.', '', 0),
(1211, 'koKR', 'Dziękuję ci, $n. I powodzenia.', '', 0),
(1223, 'koKR', 'Athrikus wskazuje na ciebie i ryczy słowa, które rozdzierają ci uszy od środka. To ostatnie, co słyszysz.', '', 0),
(1224, 'koKR', '', 'Wreszcie moja dusza zazna spokoju... Och, najdroższy Cerelleanie...', 0),
(1227, 'koKR', 'Ponury Pazur?! Spokojnie, przyjacielu... gdzie jest twój pan, Volcor?', '', 0),
(1229, 'koKR', 'Spokojnie, spokojnie, przyjacielu. Chwileczkę...', '', 0),
(1230, 'koKR', 'Już... to powinno pomóc. A teraz powiedz mi, co się stało, Ponury Pazurze.', '', 0),
(1232, 'koKR', 'Rozumiem, przyjacielu. Znajdę kogoś, kto pomoże twojemu panu. Wracaj teraz do niego albo przynajmniej trzymaj się w pobliżu.', '', 0),
(1236, 'koKR', 'Jeszcze raz dziękuję, $n. Teraz ruszę w stronę drogi. Gdy tylko będziesz $gmógł:mogła;, odszukaj Terenthisa i daj mu znać, że uciekliśmy.', '', 0),
(1237, 'koKR', 'Cóż, teraz albo nigdy. Pamiętaj, gdy już bezpiecznie dotrzemy do drogi, wróć do Terenthisa i daj mu znać, że uciekliśmy.', '', 0),
(1238, 'koKR', '%s ryczy, zmienia postać i odbiega.', '', 0),
(1243, 'koKR', 'Udało się, przyjacielu. Pamiętaj, by odszukać Terenthisa i powiedzieć mu, że jesteśmy bezpieczni. Jeszcze raz dziękuję.', '', 0),
(1244, 'koKR', 'Ja też się cieszę, że cię widzę, Ponury! Wygląda na to, że nie każdego obcego trzeba się bać, co, Ponury? Terenthis sowicie nagrodzi tego śmiałka.', '', 0),
(1245, 'koKR', 'Co to był za odgłos? Brzmiało jak ryk.', '', 0),
(1246, 'koKR', '%s zaczyna rzucać czar na Ponurego Pazura.', '', 0),
(1247, 'koKR', 'Zaraz się do tego zabiorę, $n.', '', 0),
(1248, 'koKR', 'No więc... gdzie ja podziałem nici i igłę? Ach! Są tutaj...', '', 0),
(1249, 'koKR', '%s zaczyna rzucać czar, gdy odbierasz od niego płaszcz.', '', 0),
(1278, 'koKR', 'Anayo...? Czy oczy mnie nie mylą? Czy to naprawdę ty?', '', 0),
(1280, 'koKR', 'Że też los jest tak okrutny, by po tysiącu lat rozłąki dać nam tylko tę chwilę...', '', 0),
(1281, 'koKR', 'Czy mnie nienawidzisz, ukochana? Za to, że musiałem zniszczyć twoją żywą postać, by twój duch został uwolniony z nieszczęsnej niewoli?', '', 0),
(1286, 'koKR', 'Nie! Anayo... Anayo! Nie opuszczaj mnie! Proszę...', '', 0),
(1287, 'koKR', 'Jak, ukochana? Jak znajdę siłę, by stawić czoła wiekom tego świata bez ciebie u mego boku...', '', 0),
(1289, 'koKR', 'Idź już, $n. Odnajdź Volcora... i pamiętaj, że chroniąca cię magia pryśnie, jeśli z kimkolwiek zrobisz cokolwiek poza rozmową.', '', 0),
(1305, 'koKR', 'Witaj, Selarin. Obawiam się, że w tej chwili nie mogę ci pomóc, ale może któryś z poszukiwaczy przygód tu, w Auberdine...', '', 0),
(1384, 'koKR', 'Jeśli masz czas, Ponuremu Pazurowi i jego panu, Volcorowi, przydałaby się twoja pomoc. Jeśli cię to zainteresowało, porozmawiaj ze mną...', '', 0),
(1449, 'koKR', 'Moja... moja moc osłabła... Zapłacisz za tę zuchwałość!', '', 0),
(1450, 'koKR', 'Nie! Nie możesz mnie pokonać!', '', 0),
(1459, 'koKR', 'Rozbicie tego kamienia dusz to proste zadanie!', '', 0),
(1473, 'koKR', 'W takim razie musimy położyć kres Athrikusowi Narassinowi. Powiedz mi, duchu, gdzie znajdziemy pozostałe kamienie dusz, by zniweczyć jego magię?', '', 0),
(2702, 'koKR', 'Maszyna obraca się w twoją stronę.$B$BZ tyłu maszyny widnieje pusty, dziwnie wykrzywiony otwór, a pod nim wygrawerowany napis: „Włazność kap\'tana Gelkaka Gyromasta”', '', 0),
(2703, 'koKR', 'Przekręć klucz, by uruchomić maszynę.', 'Przekręć klucz, by uruchomić maszynę.', 0),
(2704, 'koKR', 'JARRR! Majtku, coś ty $gnarobił:narobiła;?! Oszalał! Zabić luki! Podnieść maszt! ARRRR! Ratuj się, kto może!', '', 0),
(2741, 'koKR', 'Klucz Gelkaka wsuwa się w pusty otwór.', '', 0),
(2755, 'koKR', 'Witaj, jestem Tharnariun Opiekun Drzew.', '', 0),
(2843, 'koKR', '', 'Witaj, miło mi cię poznać.\n', 0),
(3012, 'koKR', '*Jednostka Młóckotłukator Pierwszy Oficer gotowa do marszu*', '', 0),
(3744, 'koKR', 'O nie! Nadchodzą!', '', 0),
(5526, 'koKR', 'Witaj, $gchłopcze:panienko;! Jeśli szukasz najlepszych okazji poza samą Żelazną Kuźnią, to dobrze $gtrafiłeś:trafiłaś;.', '', 0),
(5528, 'koKR', 'Cześć. Jestem Gubber Blump.', '', 0),
(5529, 'koKR', 'Gubber, nie umiem łowić ryb.\n', 'Gubber, nie umiem łowić ryb.', 0),
(5530, 'koKR', 'Gubber, nie mam wędki.', 'Gubber, nie mam wędki.', 0),
(5531, 'koKR', 'Wędkowanie to łatwizna. Bierzesz wędkę z żyłką, może zakładasz jakąś przynętę i zarzucasz do wody. I ani się obejrzysz, a ryby zaczną brać.', '', 0),
(5532, 'koKR', 'Mam przy sobie kilka zapasowych; jak mi oddasz, ile za nie zapłaciłem, jedna jest twoja. Przynętę też mam.', '', 0),
(5684, 'koKR', '%s przyłapuje cię, jak grzebiesz w obozowych zapasach owoców, i rzuca się na ciebie!', '', 0),
(5685, 'koKR', '%s wyłania się z chaty z bali i przyłapuje cię, jak grzebiesz w zapasach zboża!', '', 0),
(5728, 'koKR', 'Coś tam już umiesz. Dość, żeby się czegoś nauczyć, tak myślę. Zobaczmy, czego mogę cię nauczyć, co?', '', 0),
(5937, 'koKR', 'Bądź oczyszczony!', '', 0),
(6540, 'koKR', 'Liladris czeka na mnie w Posterunku Maestry, więc powinniśmy się pospieszyć, $n.', '', 0),
(6541, 'koKR', '%s zaczyna przysypiać...', '', 0),
(6542, 'koKR', '%s nagle zasypia.', '', 0),
(6543, 'koKR', 'Uaaaaaaaaaa...', '', 0),
(6544, 'koKR', 'Och, jestem taki zmęczony...', '', 0),
(6545, 'koKR', 'Nie masz nic przeciwko temu, żebym na chwilę się tu zatrzymał, prawda?', '', 0),
(6612, 'koKR', '%s budzi się!', '', 0),
(6643, 'koKR', 'Och, widzę stąd Liladrisa... Powiesz mu, że już jestem, dobrze?', '', 0),
(6811, 'koKR', '%s wygląda na bardzo śpiącego...', '', 0),
(6813, 'koKR', 'To wygląda na idealne miejsce na drzemkę...', '', 0),
(6867, 'koKR', 'Miej się na baczności! Furbolgów z Czarnego Lasu jest tu mnóstwo...', '', 0),
(6868, 'koKR', 'Cicho tu... Za cicho...', '', 0),
(7199, 'koKR', '', 'Skończyły mi się strzały! Obawiam się, że jeśli nadejdzie ich więcej, będziesz $gmusiał:musiała; stawić im czoła $gsam:sama;, przyjacielu.', 0),
(7200, 'koKR', '', 'Czekaj... słyszysz? Coś nadciąga od zachodu!', 0),
(7201, 'koKR', '', 'Chwała Elunie! Nie wiem, czy przetrwałabym ten dzień bez ciebie, przyjacielu.', 0),
(7202, 'koKR', '', 'Noga czuje się już znacznie lepiej, lek musi działać. Wybacz, ale muszę złożyć przełożonym raport z tego, co tu zaszło.\n', 0),
(7328, 'koKR', '', 'Porozmawiaj, proszę, ze strażniczką Onaeyą w Posterunku Maestry w Jesionowej Kniei. Dopilnuje, by cię należycie nagrodzono za dzisiejsze męstwo.', 0),
(7805, 'koKR', '', 'Cześć! Jestem Jenna! A ty?', 0),
(8065, 'koKR', 'Szycie wymaga pewnej ręki. I cierpliwości... przede wszystkim cierpliwości.', '', 0),
(8067, 'koKR', 'Chętnie wezmę cię pod swoje skrzydła. Zaczynajmy.', '', 0),
(8098, 'koKR', '', 'Hipogryf to szlachetne zwierzę, dumne i szybkie. Szkolenie hipogryfów to zaszczyt, a potrafią w krótkim czasie zanieść jeźdźca bardzo daleko.', 0),
(8106, 'koKR', 'Z północnego doku możesz wsiąść na statek, który zabierze cię do Wioski Rut\'theran i Darnassus. Z południowego doku znajdziesz przeprawę przez Wielkie Morze do Portu Wichrogrodu. Dok zachodni, na końcu pomostu, prowadzi na Wyspę Lazurowej Mgły, niedaleko Exodaru. Bezpiecznej podróży!', '', 0),
(8503, 'koKR', '', 'Niech Elune kroczy z tobą, $N. Świątynia Księżyca przybyła z pomocą strapionym mieszkańcom Auberdine.', 0),
(9024, 'koKR', '', 'Znam te lasy, jakby były częścią mnie... ale wiedz, że wciąż można się od nich wiele nauczyć i wciąż kryją wiele niebezpieczeństw.', 0),
(9025, 'koKR', 'Raene, $gzgubiłem:zgubiłam; Różdżkę przemiany Dartola.', 'Raene, $gzgubiłem:zgubiłam; Różdżkę przemiany Dartola.', 0),
(9026, 'koKR', '', 'Tak, spodziewałam się, że wrócisz. Wysłałam wcześniej Korrę i natknęła się na Różdżkę Dartola porzuconą w lesie.$B$BTak ciężko pracowaliśmy, by ją odzyskać, $n. Proszę, uważaj, byś w przyszłości nie $gobchodził:obchodziła; się z nią tak niedbale.', 0),
(9027, 'koKR', '', '$GWykonałeś:Wykonałaś; misję Teronisa. Dziękuję ci za wszystko, co $gzrobiłeś:zrobiłaś;, $n.', 0),
(9431, 'koKR', 'Tharnariunie, $gzgubiłem:zgubiłam; pułapkę. Czy możesz dać mi kolejną?', 'Tharnariunie, $gzgubiłem:zgubiłam; pułapkę. Czy możesz dać mi kolejną?', 0),
(11565, 'koKR', 'Gdzie jest Nestor Nocny Wiatr?', 'Gdzie jest Nestor Nocny Wiatr?', 0),
(11566, 'koKR', 'Nestor Nocny Wiatr spędza dni przy kapliczce w Jaedenarze w Spaczonej Kniei.', 'Nestor Nocny Wiatr spędza dni przy kapliczce w Jaedenarze w Spaczonej Kniei.', 0),
(11567, 'koKR', 'Gdzie jest Nestor Rzeczna Pieśń?', 'Gdzie jest Nestor Rzeczna Pieśń?', 0),
(11568, 'koKR', 'Nestor Rzeczna Pieśń mieszka obecnie w wiosce Astranaar w Jesionowej Kniei.', 'Nestor Rzeczna Pieśń mieszka obecnie w wiosce Astranaar w Jesionowej Kniei.', 0),
(14143, 'koKR', 'Mamusiu!', '', 0),
(39497, 'koKR', 'Mamusiu!', 'Mamusiu!', 0);
